insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('session-agenda-setter', 'Session Agenda Setter', 'worksheet'::resource_kind, 'A short worksheet for bringing one or two items the client wants to cover before a session starts.', 'Use it to give the client a stake in the hour and keep session time from drifting to whatever comes up last.', array['Adults', 'Teens']::text[], '5 minutes', 'Hand this to the client a few minutes before the session, or have them fill it out in the waiting room; the two-item cap keeps someone who tends to arrive with a long list from using the whole hour on the first topic. Some clients leave it blank out of habit, so a verbal prompt at check-in works as well as the paper does. Keep it visible during the hour as a light anchor to return to if the conversation wanders.', '[{"id": "f0", "type": "textarea", "label": "What is the one thing you most want to talk about today?"}, {"id": "f1", "type": "textarea", "label": "What is a second thing, if there''s time?"}, {"id": "f2", "type": "textarea", "label": "Is there anything urgent that can''t wait until later in the session?"}, {"id": "f3", "type": "textarea", "label": "How much time do you think each item needs?"}]'::jsonb, array['session structure', 'goal setting', 'planning']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('readiness-and-confidence-ruler', 'Readiness and Confidence Ruler', 'worksheet'::resource_kind, 'A 0-to-10 scale worksheet rating how important a change feels and how confident the client is that they can make it.', 'Use it to open a conversation about ambivalence and turn a stuck should into a concrete next step.', array['Adults', 'Teens']::text[], '10 minutes', 'Ask the client to mark where they land right now on two separate 0-to-10 lines, one for importance and one for confidence, then ask why they picked that number and not one lower; the answer surfaces their own reasons for change instead of the clinician''s. A low confidence score next to a high importance score points straight at what to problem-solve next. Revisiting the same two lines across sessions shows movement a client might otherwise miss.', '[{"id": "f0", "type": "textarea", "label": "On a scale of 0 to 10, how important is this change to you right now?"}, {"id": "f1", "type": "textarea", "label": "What made you pick that number instead of a lower one?"}, {"id": "f2", "type": "textarea", "label": "On a scale of 0 to 10, how confident are you that you could make this change?"}, {"id": "f3", "type": "textarea", "label": "What would move your confidence up by even one point?"}, {"id": "f4", "type": "textarea", "label": "What might get in the way?"}]'::jsonb, array['motivation', 'goal setting', 'readiness']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('habit-stacking-planner', 'Habit Stacking Planner', 'worksheet'::resource_kind, 'A worksheet for anchoring a new habit to a routine the client already does every day.', 'Use it to help a change stick by attaching it to an existing cue instead of relying on memory alone.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list three routines they already do without fail, such as making coffee or sitting down at their desk, and pick one to attach the new habit to immediately after. The habit should take under two minutes at first; ambition here works against the client, since a stack that takes too long gets skipped on a busy day. Check back the following week on whether the anchor held or whether a different routine would work better.', '[{"id": "f0", "type": "textarea", "label": "What are three things you already do every day without having to think about it?"}, {"id": "f1", "type": "textarea", "label": "Which one of those could you attach a new habit to?"}, {"id": "f2", "type": "textarea", "label": "What is the smallest version of the new habit you could do right after it?"}, {"id": "f3", "type": "textarea", "label": "What might make you skip the anchor routine itself on a hard day?"}, {"id": "f4", "type": "textarea", "label": "How will you notice and restart if you miss a day?"}]'::jsonb, array['habits', 'planning', 'self-monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('guilt-and-shame-sorter', 'Guilt and Shame Sorter', 'worksheet'::resource_kind, 'A sorting worksheet that separates guilt about a specific action from shame about the self as a whole.', 'Use it to help a client tell the two apart so guilt can lead to repair instead of curdling into shame.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk the client through a recent situation twice: once naming the guilt sentence, I did something wrong, and once naming the shame sentence, I am something wrong, then ask which one is actually true given what happened. Most people arrive fused, so slowing down to write both versions side by side is often the first time a client sees that only the first one points anywhere useful. A client who insists the shame sentence is simply a fact is worth a full session of its own before rushing to the repair step.', '[{"id": "f0", "type": "textarea", "label": "What happened, in a few plain sentences?"}, {"id": "f1", "type": "textarea", "label": "What is the guilt sentence: what did you do?"}, {"id": "f2", "type": "textarea", "label": "What is the shame sentence: what does it say about you as a person?"}, {"id": "f3", "type": "textarea", "label": "Looking at both sentences, which one is actually supported by what happened?"}, {"id": "f4", "type": "textarea", "label": "If it''s the guilt sentence, what''s one step toward repair?"}]'::jsonb, array['shame', 'guilt', 'self-criticism']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('self-compassion-break-card', 'Self-Compassion Break Card', 'worksheet'::resource_kind, 'A pocket card walking the client through a three-step self-compassion break in the middle of a hard moment.', 'Use it to give the client something brief enough to reach for in the moment, not just after the fact.', array['Adults', 'Teens', 'Groups']::text[], '5 minutes', 'Teach the three steps in session first: naming that this is a hard moment, remembering that struggle is part of being human, and offering a hand or words the kind of comfort a friend would get, then send the card home as a reminder rather than a script to read cold. Some clients resist the second step, insisting their situation is uniquely bad; naming that resistance is useful material, not a sign the exercise failed. A short practice run in session helps the card trigger a memory of doing it, not a new task.', '[{"id": "f0", "type": "textarea", "label": "Name what''s happening: what would you say to yourself right now?"}, {"id": "f1", "type": "textarea", "label": "Remind yourself: how is this moment connected to being human, not just you?"}, {"id": "f2", "type": "textarea", "label": "Offer yourself something kind, in the words or gesture you''d give a friend."}, {"id": "f3", "type": "textarea", "label": "What changed, even slightly, after the three steps?"}]'::jsonb, array['self-compassion', 'mindfulness', 'self-soothing']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('double-standard-technique', 'Double Standard Technique', 'cbt'::resource_kind, 'A dialogue worksheet comparing what the client tells themselves to what they''d tell a friend in the same spot.', 'Use it to expose a harsh self-judgment by testing it against the standard the client already applies to others.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to write their self-critical thought word for word, then write what they''d say to a close friend who told them the exact same thing about themselves. The gap between the two columns is usually the whole point; most clients spot it without being told, which lands harder than the clinician naming it for them. If the client insists their own case is genuinely different from a friend''s, ask what specifically makes it different rather than accepting the claim at face value.', '[{"id": "f0", "type": "textarea", "label": "What is the exact thought you have about yourself right now?"}, {"id": "f1", "type": "textarea", "label": "If a close friend told you they were thinking that about themselves, what would you say back to them?"}, {"id": "f2", "type": "textarea", "label": "What''s different about your two answers?"}, {"id": "f3", "type": "textarea", "label": "What would it take to believe your own answer about the friend?"}]'::jsonb, array['core beliefs', 'self-criticism', 'thinking traps']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('problem-solving-steps-guide', 'Problem-Solving Steps Guide', 'cbt'::resource_kind, 'A step-by-step worksheet for defining a problem, generating options, and picking one to try.', 'Use it to slow down a client who jumps straight to worry or avoidance instead of working the problem itself.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Work through the steps in order: state the problem in one specific sentence, list every option without judging it yet, weigh the realistic ones, pick one, then set a date to check how it went. Clients often want to skip straight to solutions or generate only good options, so hold them to a genuinely wide brainstorm before any evaluating starts. This fits problems that are actually solvable; a worry with no real decision point underneath it is better routed to a worry or acceptance tool instead.', '[{"id": "f0", "type": "textarea", "label": "State the problem in one specific sentence."}, {"id": "f1", "type": "textarea", "label": "List every option you can think of, even bad ones; don''t filter yet."}, {"id": "f2", "type": "textarea", "label": "Which two or three options are realistic given your situation?"}, {"id": "f3", "type": "textarea", "label": "Which one will you try first, and when?"}, {"id": "f4", "type": "textarea", "label": "How will you know, and when will you check back, on whether it worked?"}]'::jsonb, array['problem solving', 'planning', 'decisions']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('point-counterpoint-technique', 'Point-Counterpoint Technique', 'cbt'::resource_kind, 'A two-column dialogue exercise where the client argues both for and against a rigid core belief out loud.', 'Use it to loosen a core belief that''s held up to logic but hasn''t budged in daily life.', array['Adults']::text[], '20 minutes', 'The clinician or the client takes the point side, voicing the belief as strongly as it actually feels, while the other takes counterpoint, arguing back with the client''s own lived evidence; switch roles partway through so the client also has to argue against the belief in their own voice. This works best after questioning has already surfaced some counter-evidence, since the exercise is about practicing conviction, not discovering it fresh. Stop if it turns into the client simply restating the belief louder; that''s a cue to slow back down to gathering evidence.', '[{"id": "f0", "type": "textarea", "label": "State the belief exactly as it feels true, as strongly as you can."}, {"id": "f1", "type": "textarea", "label": "Now argue back against it using something you actually know from your own life."}, {"id": "f2", "type": "textarea", "label": "Switch roles: argue for the belief, then argue against it in your own voice."}, {"id": "f3", "type": "textarea", "label": "Which side felt more convincing, and why?"}]'::jsonb, array['core beliefs', 'belief change', 'evidence']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('self-instructional-training-script', 'Self-Instructional Training Script', 'cbt'::resource_kind, 'A script the client writes and rehearses to talk themselves through a stressful task step by step.', 'Use it to replace spiraling self-talk with a planned, neutral narration the client can lean on under pressure.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write out the stressful task in stages, preparing, starting, handling a setback partway through, and finishing, with one calm, instructional line for each stage, the way a coach would narrate rather than the way an anxious inner voice usually does. Rehearse it out loud in session at least once before it goes home, since reading it silently doesn''t build the same automatic reach for it under pressure. Revise the setback line often; it''s usually the one that gets skipped and the one the client needs most.', '[{"id": "f0", "type": "textarea", "label": "What is the stressful task, in one sentence?"}, {"id": "f1", "type": "textarea", "label": "What will you say to yourself while preparing for it?"}, {"id": "f2", "type": "textarea", "label": "What will you say to yourself right as you start?"}, {"id": "f3", "type": "textarea", "label": "What will you say to yourself if something goes wrong partway through?"}, {"id": "f4", "type": "textarea", "label": "What will you say to yourself once it''s done?"}]'::jsonb, array['self-talk', 'coping skills', 'planning']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('habit-reversal-training-log', 'Habit Reversal Training Log', 'cbt'::resource_kind, 'A tracking log pairing early awareness of an unwanted habit with a planned competing action.', 'Use it to build the moment-to-moment awareness a client needs before a competing response can interrupt a habit.', array['Adults', 'Teens']::text[], 'One week', 'Start with awareness alone for the first few days: the client simply logs each time they notice the habit starting, without yet trying to stop it, so they learn to catch it earlier each time. Once catches happen reliably before the habit is underway, add the second column and have the client swap in one specific competing action, such as clenching a fist or pressing their tongue to the roof of their mouth, every time they catch the urge. Progress is usually uneven; a bad day is data about a trigger, not a sign the log isn''t working.', '[{"id": "f0", "type": "textarea", "label": "What time did you notice the habit starting, or about to start?"}, {"id": "f1", "type": "textarea", "label": "What was happening right before you noticed it?"}, {"id": "f2", "type": "textarea", "label": "Did you catch it before, during, or after it started?"}, {"id": "f3", "type": "textarea", "label": "If you used the competing action, what did you do instead?"}, {"id": "f4", "type": "textarea", "label": "What made this catch easier or harder than usual?"}]'::jsonb, array['habits', 'self-monitoring', 'urges']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('chinese-finger-trap-metaphor', 'Chinese Finger Trap Metaphor', 'act'::resource_kind, 'A hands-on demonstration of how straining against an unwanted feeling only pulls it tighter.', 'Use it to help a client feel why easing into a feeling loosens it faster than fighting it does.', array['Adults', 'Teens']::text[], '10 minutes', 'Bring an actual finger trap if you have one, or have the client mime pulling apart clasped hands; pulling outward against the resistance tightens the grip, just as straining against an unwanted feeling or urge tends to pull it tighter. Guide them to press gently inward instead and notice the slack that opens, then name a feeling or urge in their week where the same pulling shows up. Keep it brief and physical rather than letting it turn into explanation, and close by naming one small step toward something they value, even with the feeling still there.', '[{"id": "f0", "type": "textarea", "label": "What did you notice in your body as you pulled against the trap?"}, {"id": "f1", "type": "textarea", "label": "Where in your week do you catch yourself pulling against a feeling or urge the same way?"}, {"id": "f2", "type": "textarea", "label": "What happens if you ease in instead of pulling away?"}, {"id": "f3", "type": "textarea", "label": "What is one step you could take toward something that matters to you, even with the feeling still there?"}]'::jsonb, array['acceptance', 'metaphor', 'defusion', 'willingness']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('joe-the-bum-metaphor', 'Joe the Bum Metaphor', 'act'::resource_kind, 'A short story about an unwelcome houseguest that reframes fighting a feeling as making room for it instead.', 'Use it to shift a client from evicting a feeling to letting it stay while life goes on around it.', array['Adults', 'Teens']::text[], '10 minutes', 'Tell the client about a host at a party when a loud, unwelcome guest shows up at the door; the host can spend the night trying to force the guest out, missing the party in the process, or let the guest stay in the corner while everyone else keeps mingling. Ask the client to name the feeling, urge or memory that is their own uninvited guest, and where they usually spend energy trying to throw it out. Clarify that letting the guest stay is not agreeing with it, just making room so the party can continue, then connect it to what hosting their own life would look like this week.', '[{"id": "f0", "type": "textarea", "label": "Who or what is the unwelcome guest showing up at your door lately?"}, {"id": "f1", "type": "textarea", "label": "What does trying to throw the guest out usually look like for you?"}, {"id": "f2", "type": "textarea", "label": "What would it look like to let the guest stay in the corner while you keep hosting?"}, {"id": "f3", "type": "textarea", "label": "What is one part of your own party you''d like to get back to this week?"}]'::jsonb, array['acceptance', 'metaphor', 'willingness', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('radio-doom-and-gloom', 'Radio Doom and Gloom', 'act'::resource_kind, 'A defusion exercise that has a client name their harshest inner commentary like a radio station playing on.', 'Use it to help a client notice a running stream of self-criticism as a broadcast, not a fact.', array['Adults', 'Teens', 'Groups']::text[], '10 minutes', 'Ask the client to picture their harshest inner commentary as a radio station playing in the background, and have them give it a name such as Radio Doom and Gloom, plus a tagline it might use to introduce itself. Practice noticing when the station switches on during the day and naming it, silently or out loud, rather than arguing with what it says or getting hooked. Watch for clients who turn the exercise into fighting the station; the aim is not to shut it off but to notice it is playing while still choosing what they do next.', '[{"id": "f0", "type": "textarea", "label": "What would you name your mind''s harshest radio station?"}, {"id": "f1", "type": "textarea", "label": "What is a tagline that station uses to introduce itself?"}, {"id": "f2", "type": "textarea", "label": "When did you notice the station switch on this week?"}, {"id": "f3", "type": "textarea", "label": "What did you choose to do while it was playing?"}]'::jsonb, array['defusion', 'core ACT', 'self-criticism']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('eulogy-values-exercise', 'Eulogy Values Exercise', 'act'::resource_kind, 'A guided reflection where a client imagines what they would want said about them to surface what matters.', 'Use it to help a client separate their real values from the goals or approval driving today''s choices.', array['Adults']::text[], '20 minutes', 'Have the client close their eyes or write in silence while you read a short prompt: imagine a gathering years from now where people who matter most are speaking about the life they lived, and picture what they hope is said about how they showed up, treated people and spent their time. Let them draft a few lines in that voice, then compare it to how they are actually spending this week. The exercise can surface grief or regret quickly, so slow the pace for a client carrying loss and keep the focus on direction, not scorekeeping.', '[{"id": "f0", "type": "textarea", "label": "What do you hope is said about how you treated the people around you?"}, {"id": "f1", "type": "textarea", "label": "What do you hope is said about how you spent your time and energy?"}, {"id": "f2", "type": "textarea", "label": "Where does this week''s schedule already match that? Where does it not?"}, {"id": "f3", "type": "textarea", "label": "What is one small shift that would bring this week closer to that direction?"}]'::jsonb, array['values', 'core ACT', 'life review']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('pink-elephant-suppression-exercise', 'Pink Elephant Suppression Exercise', 'act'::resource_kind, 'A one-minute thought-suppression demonstration that shows a client how trying not to think something backfires.', 'Use it to make the cost of thought control concrete before shifting the work toward willingness.', array['Adults', 'Teens', 'Groups']::text[], '5 minutes', 'Ask the client to close their eyes for one minute and try as hard as they can not to think about a pink elephant, then check in on how often the elephant showed up anyway. Draw the parallel to the effort the client puts into pushing away an unwanted thought, feeling or memory in daily life, and ask where trying not to think about it tends to backfire the same way. Some clients treat this as a party trick rather than personal data, so slow down and connect it directly to a thought or urge they actually struggle with, then use it as the bridge into practicing willingness instead of control.', '[{"id": "f0", "type": "textarea", "label": "How many times did the pink elephant show up during the minute?"}, {"id": "f1", "type": "textarea", "label": "What thought, feeling or memory do you usually try hardest not to think about?"}, {"id": "f2", "type": "textarea", "label": "What has trying not to think about it cost you?"}, {"id": "f3", "type": "textarea", "label": "What would it look like to let the thought be there without fighting it?"}]'::jsonb, array['defusion', 'willingness', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-skills-card', 'IMPROVE the Moment Skills Card', 'dbt'::resource_kind, 'A card walking a client through each letter of IMPROVE for getting through an intense moment.', 'Use it to give a client a menu of ways to ease a hard moment when the crisis has not fully passed.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk the client through each letter of IMPROVE, imagery, meaning, connection to something larger, relaxation, one thing at a time, a brief vacation, and encouragement, and have them write one concrete example next to each letter rather than leaving it generic. Practice one or two of the strongest fits out loud in session so the client has already rehearsed the motion before they need it. Watch for clients who fill in all seven from habit without noticing which ones actually shift their body; a shorter, practiced list beats a full card nobody can recall under pressure.', '[{"id": "f0", "type": "textarea", "label": "Imagery: what picture could you call up that helps you feel steadier?"}, {"id": "f1", "type": "textarea", "label": "Meaning: what meaning or silver lining, if any, could you find in this moment?"}, {"id": "f2", "type": "textarea", "label": "Connection: what larger sense of support could you lean on right now?"}, {"id": "f3", "type": "textarea", "label": "Relaxation: what in your body could you loosen or soften right now?"}, {"id": "f4", "type": "textarea", "label": "One thing at a time: what is the single next thing in front of you?"}, {"id": "f5", "type": "textarea", "label": "Vacation: what would a five-minute break from this look like?"}, {"id": "f6", "type": "textarea", "label": "Encouragement: what would you say to a friend in this exact moment?"}]'::jsonb, array['distress tolerance', 'crisis', 'self-soothing']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-practice', 'Turning the Mind Practice', 'dbt'::resource_kind, 'A repeated-choice practice where a client turns their mind back toward accepting a hard fact each time it drifts.', 'Use it to build the muscle of choosing acceptance again and again rather than expecting it to stick once.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client picture a fork in the road where one path is fighting a fact and the other is accepting it as it is right now, without that meaning they approve of it. Ask them to physically turn their body or hands toward the accepting path each time they notice themselves back on the fighting one, repeating the turn as many times as it takes rather than treating one turn as final. Normalize that most people turn their mind dozens of times over one hard fact, and that this is practice, not failure; pair it with a specific situation from the client''s week.', '[{"id": "f0", "type": "textarea", "label": "What is the fact or situation you keep fighting against?"}, {"id": "f1", "type": "textarea", "label": "What does the fighting path usually sound like in your head?"}, {"id": "f2", "type": "textarea", "label": "What does turning toward acceptance look or feel like for you?"}, {"id": "f3", "type": "textarea", "label": "How many times did you notice yourself turning back this week?"}]'::jsonb, array['radical acceptance', 'willingness', 'mindfulness']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('think-skill-practice-card', 'THINK Skill Practice Card', 'dbt'::resource_kind, 'A card that walks a client through THINK to build empathy for someone who irritated them before they respond.', 'Use it to slow a client down between a trigger and a response by working through each letter of THINK.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'Have the client pick a recent moment someone irritated or angered them, then walk through THINK: think about what the other person might have been feeling, build empathy for their situation, notice interpretations being jumped to, look for kindness that could be offered instead, and consider how the client would want to be seen if roles were reversed. Encourage more than one interpretation of the other person''s behavior, since the exercise loses power if the client settles on the first, least generous read. Works best once a conflict has cooled enough to reflect, not relitigate.', '[{"id": "f0", "type": "textarea", "label": "What did the other person do that irritated or angered you?"}, {"id": "f1", "type": "textarea", "label": "What might they have been thinking or feeling in that moment?"}, {"id": "f2", "type": "textarea", "label": "What is one kinder interpretation of their behavior, even if you''re not sure it''s true?"}, {"id": "f3", "type": "textarea", "label": "What would kindness look like in your response?"}, {"id": "f4", "type": "textarea", "label": "How would you want to be seen if you were in their position?"}]'::jsonb, array['interpersonal effectiveness', 'communication', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('build-mastery-activity-log', 'Build Mastery Activity Log', 'dbt'::resource_kind, 'A weekly log for scheduling one activity that stretches a client''s skill just past what feels comfortable.', 'Use it to build a client''s sense of competence as a buffer against emotional vulnerability over time.', array['Adults', 'Teens']::text[], 'One week', 'Have the client pick one activity a day that is slightly harder than what already feels easy but still realistic to finish, not something so far out of reach that it sets them up to quit. Log the activity, how it went, and a one-line note on what it showed them they can do, building toward a felt sense of competence rather than perfection. Coach clients away from picking only chores or only enjoyable activities; the skill is specifically about a stretch, so a walk that runs a little longer or a hard conversation practiced out loud both count as long as it pushes just past the current edge.', '[{"id": "f0", "type": "textarea", "label": "What activity did you pick for today, and why does it stretch you slightly?"}, {"id": "f1", "type": "textarea", "label": "How did it actually go?"}, {"id": "f2", "type": "textarea", "label": "What did finishing it show you that you can do?"}, {"id": "f3", "type": "textarea", "label": "What will tomorrow''s slightly harder step be?"}]'::jsonb, array['emotion regulation', 'confidence', 'habits']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-log', 'Mindfulness of Current Emotion Log', 'dbt'::resource_kind, 'A log for observing and naming a strong emotion as it moves through the body without pushing it away.', 'Use it to build a client''s capacity to stay with a feeling long enough to watch it change on its own.', array['Adults', 'Teens']::text[], '10 minutes', 'When a strong feeling shows up, have the client pause, name it as specifically as they can, and locate where it shows up in the body, then simply observe it rising, peaking and settling the way a wave does, without pushing it away, holding onto it or acting on the urge that comes with it. Remind them the feeling is not who they are; it is something moving through them right now. Clients often try to reason their way out of the feeling instead of observing it, so redirect gently back to sensation and breath.', '[{"id": "f0", "type": "textarea", "label": "What emotion showed up, named as specifically as you can?"}, {"id": "f1", "type": "textarea", "label": "Where did you feel it in your body?"}, {"id": "f2", "type": "textarea", "label": "What did you notice as you watched it rise and then start to settle?"}, {"id": "f3", "type": "textarea", "label": "What urge came with it, and did you act on it or just notice it?"}]'::jsonb, array['emotion regulation', 'mindfulness', 'emotion identification']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('digital-boundaries-agreement', 'Digital Boundaries Agreement', 'couples'::resource_kind, 'Partner A and Partner B each name one phone habit that gets in the way of connection.', 'Use it to turn recurring phone friction into one specific agreement both partners chose together.', array['Couples']::text[], '30 minutes', 'Have each partner pick just one habit rather than a full list, or the conversation turns into a grievance session. The agreement should be specific and revisited in a month — vague promises like less phone time rarely hold, while phones stay in the kitchen after nine does. Watch for one partner using the exercise to score points about the other''s habits instead of naming their own.', '[{"id": "f0", "type": "textarea", "label": "One screen habit of mine that gets in the way"}, {"id": "f1", "type": "textarea", "label": "One screen habit of my partner''s that gets in the way"}, {"id": "f2", "type": "textarea", "label": "What I need instead, in one sentence"}, {"id": "f3", "type": "textarea", "label": "What my partner needs instead, in one sentence"}, {"id": "f4", "type": "textarea", "label": "Our specific agreement, with a time and place"}, {"id": "f5", "type": "textarea", "label": "How we will check in on this in one month"}]'::jsonb, array['communication', 'boundaries', 'connection']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('in-law-boundary-script', 'In-Law Boundary Script', 'couples'::resource_kind, 'The couple writes a script together for a specific extended-family boundary, spoken and supported.', 'Use it to turn a vague complaint about in-laws into a boundary both partners can say out loud.', array['Couples']::text[], '30 minutes', 'Name the actual situation, not the general in-law relationship — a holiday visit, a phone call, an unsolicited comment. The partner whose family it is usually needs to deliver the boundary, with the other partner''s support named out loud beforehand so it does not surface as a fight later. Rehearse the exact line in session before it gets said at home.', '[{"id": "f0", "type": "textarea", "label": "The specific situation this boundary covers"}, {"id": "f1", "type": "textarea", "label": "The boundary, in one sentence"}, {"id": "f2", "type": "textarea", "label": "Who will say it, in their own words"}, {"id": "f3", "type": "textarea", "label": "How the other partner will show support beforehand"}, {"id": "f4", "type": "textarea", "label": "What we will do if it is not respected"}]'::jsonb, array['boundaries', 'family', 'communication']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('financial-values-interview', 'Financial Values Interview', 'couples'::resource_kind, 'Each partner interviews the other with structured questions about their money history and worries.', 'Use it to surface the beliefs about money that drive conflict before the couple sets a shared plan.', array['Couples']::text[], '30 minutes', 'Run this before any budgeting conversation — couples who jump straight to numbers often skip the history that explains why a figure feels threatening to one partner and neutral to the other. Ask partners to interview each other rather than fill it out separately, and to listen for the feeling behind each answer more than the number. Save actual budget talk for a later session.', '[{"id": "f0", "type": "textarea", "label": "What money meant in your family growing up"}, {"id": "f1", "type": "textarea", "label": "A money memory that still affects you"}, {"id": "f2", "type": "textarea", "label": "What feels safe about how we handle money now"}, {"id": "f3", "type": "textarea", "label": "What feels risky about how we handle money now"}, {"id": "f4", "type": "textarea", "label": "One thing you want your partner to understand about your money worries"}, {"id": "f5", "type": "textarea", "label": "One shared money value we already agree on"}]'::jsonb, array['values', 'communication', 'stress']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('date-night-menu-builder', 'Date Night Menu Builder', 'couples'::resource_kind, 'Each partner lists low-cost, low-effort ways to connect, then the couple builds a shared menu.', 'Use it to make time together the default instead of something the couple negotiates every week.', array['Couples']::text[], '20 minutes', 'Couples who have stopped dating often cannot picture what to do together anymore, so start with a long list before narrowing it down. Ask each partner to include at least one option under fifteen minutes for weeks with no time to spare. Post the finished menu somewhere visible at home so choosing becomes picking from a list rather than a new conversation every time.', '[{"id": "f0", "type": "textarea", "label": "My ideas for a full evening together"}, {"id": "f1", "type": "textarea", "label": "My ideas for fifteen minutes or less"}, {"id": "f2", "type": "textarea", "label": "My partner''s ideas for a full evening together"}, {"id": "f3", "type": "textarea", "label": "My partner''s ideas for fifteen minutes or less"}, {"id": "f4", "type": "textarea", "label": "Our shared menu, in order of how often we want to use it"}]'::jsonb, array['connection', 'routines', 'relationships']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('sleep-territory-negotiation', 'Sleep Territory Negotiation', 'couples'::resource_kind, 'The couple maps their mismatched sleep habits and negotiates specific changes to try.', 'Use it to turn nightly sleep friction into agreed experiments instead of a recurring resentment.', array['Couples']::text[], '25 minutes', 'Mismatched bedtimes, temperature, noise and snoring are common and rarely named directly because they feel too small to raise — until they are not. Have each partner describe their ideal sleep setup without editing it for the other, then negotiate one or two concrete changes to try for a week, from separate blankets to a later shared bedtime. Frame it as logistics, not a verdict on the relationship.', '[{"id": "f0", "type": "textarea", "label": "My ideal sleep setup, if I am honest"}, {"id": "f1", "type": "textarea", "label": "My partner''s ideal sleep setup, as I understand it"}, {"id": "f2", "type": "textarea", "label": "What currently disrupts my sleep"}, {"id": "f3", "type": "textarea", "label": "What currently disrupts my partner''s sleep"}, {"id": "f4", "type": "textarea", "label": "One change we will try this week"}, {"id": "f5", "type": "textarea", "label": "How we will check whether it helped"}]'::jsonb, array['sleep', 'communication', 'relationships']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('turn-taking-traffic-light-craft', 'Turn-Taking Traffic Light Craft', 'kids'::resource_kind, 'The child colors a paper traffic light to signal when they can wait, slow down or go.', 'Use it to give a young child a visual cue for waiting and impulse control during play.', array['Children', 'Adults']::text[], '20 minutes', 'Have the child color and cut out the three traffic light circles, then keep the finished light where play happens. The parent''s job is to hold it up silently during turn-taking moments — board games, siblings, waiting for a snack — rather than narrating instructions, so the child starts reading the cue instead of a lecture. Young children often need the yellow step named out loud the first few times before it sticks.', '[{"id": "f0", "type": "textarea", "label": "What red (stop and wait) looks like for me"}, {"id": "f1", "type": "textarea", "label": "What yellow (slow down) looks like for me"}, {"id": "f2", "type": "textarea", "label": "What green (my turn) looks like for me"}, {"id": "f3", "type": "textarea", "label": "One place at home we will use the light"}, {"id": "f4", "type": "textarea", "label": "Parent: how will you hold up the light without talking?"}]'::jsonb, array['children', 'parenting', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('friendship-recipe-card', 'Friendship Recipe Card', 'kids'::resource_kind, 'The child decorates a recipe card listing the ingredients of a good friend.', 'Use it to give a child concrete, memorable language for friendship skills.', array['Children', 'Adults']::text[], '25 minutes', 'Let the child pick the ingredients first — sharing, listening, saying sorry, taking turns — before helping them write measurements like a cup of listening or a pinch of patience, and decorate the card like a real recipe. The parent''s role is to reference the finished card by name during an actual friendship moment that week, rather than filing it away, so the language becomes something the family actually uses.', '[{"id": "f0", "type": "textarea", "label": "Ingredients for a good friend"}, {"id": "f1", "type": "textarea", "label": "The recipe, in my own words"}, {"id": "f2", "type": "textarea", "label": "A time I used one of these ingredients"}, {"id": "f3", "type": "textarea", "label": "A time a friend used one on me"}, {"id": "f4", "type": "textarea", "label": "Parent: one moment this week to point back to the recipe"}]'::jsonb, array['children', 'social skills', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('mistake-monster-craft', 'Mistake Monster Craft', 'kids'::resource_kind, 'The child draws and decorates a silly monster that stands for their fear of getting things wrong.', 'Use it to externalize a young child''s fear of mistakes into something they can talk back to.', array['Children', 'Adults']::text[], '25 minutes', 'Have the child give the monster a name, a color and a ridiculous detail or two — the sillier it looks, the easier it is to talk back to later. Once it exists on paper, practice a line the child can say to it out loud, like mistakes help me learn. The parent''s job is to name their own small mistakes out loud during the week and show how they handle them, since children copy the response more than the words.', '[{"id": "f0", "type": "textarea", "label": "My mistake monster''s name and what it looks like"}, {"id": "f1", "type": "textarea", "label": "What my mistake monster says to me"}, {"id": "f2", "type": "textarea", "label": "What I say back to it"}, {"id": "f3", "type": "textarea", "label": "A mistake I made this week and what happened next"}, {"id": "f4", "type": "textarea", "label": "Parent: a mistake you will name out loud this week"}]'::jsonb, array['children', 'self-esteem', 'parenting']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('kindness-chain-craft', 'Kindness Chain Craft', 'kids'::resource_kind, 'The child builds a growing paper chain, adding one link for every act of kindness they notice.', 'Use it to make a young child''s kind actions visible and countable over a week.', array['Children', 'Adults']::text[], 'Fifteen minutes to start, then daily', 'Cut a stack of colored paper strips ahead of time so adding a link takes seconds. A link can be an act of kindness the child did or one they received — both count, since noticing kindness from others matters as much as doing it. The parent''s role is to ask one specific question at the same point each day, like at dinner, so the habit of noticing has a fixed home rather than depending on the child remembering alone.', '[{"id": "f0", "type": "textarea", "label": "Today''s kind act — what I did"}, {"id": "f1", "type": "textarea", "label": "Today''s kind act — what someone did for me"}, {"id": "f2", "type": "textarea", "label": "How adding the link felt"}, {"id": "f3", "type": "textarea", "label": "How many links are on our chain now"}, {"id": "f4", "type": "textarea", "label": "Parent: the daily moment we will check in"}]'::jsonb, array['children', 'gratitude', 'parenting']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('listening-ears-headband-craft', 'Listening Ears Headband Craft', 'kids'::resource_kind, 'The child builds a paper headband with big ears, then plays a short listening game wearing it.', 'Use it to make active listening a physical, playful skill a young child can practice and name.', array['Children', 'Adults']::text[], '20 minutes', 'Have the child decorate the ears before the game starts, then take turns: one person tells a short story while the ear-wearer repeats back one detail before responding. Keep each turn under a minute so the exercise stays a game rather than a drill. The parent''s job is to model getting a detail wrong and fixing it, so the child sees that listening well is a skill you build, not something you either have or do not.', '[{"id": "f0", "type": "textarea", "label": "What I remember from the story I heard"}, {"id": "f1", "type": "textarea", "label": "One detail I almost missed"}, {"id": "f2", "type": "textarea", "label": "How it felt when someone listened to me"}, {"id": "f3", "type": "textarea", "label": "Parent: one moment you got it wrong and fixed it"}, {"id": "f4", "type": "textarea", "label": "One time this week we will wear the ears again"}]'::jsonb, array['children', 'communication', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('silent-line-up-challenge', 'Silent Line-Up Challenge', 'game'::resource_kind, 'The group lines up in order by a trait, like comfort with uncertainty, without speaking.', 'Use it to surface how a group reads each other nonverbally and where assumptions creep in.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Call out a trait to line up by — most to least comfortable with change works well — and set the rule that no one may speak, write or mouth words; gestures only. Give the group two minutes, then have them call out their guessed order before revealing the real one by a quick show of hands. Debrief on where the guessed order was wrong and what cue people used instead of asking directly, since that gap is usually the most useful part.', '[{"id": "f0", "type": "textarea", "label": "The trait we lined up by"}, {"id": "f1", "type": "textarea", "label": "Where I placed myself"}, {"id": "f2", "type": "textarea", "label": "Where the group guessed I was"}, {"id": "f3", "type": "textarea", "label": "What surprised me about the actual order"}, {"id": "f4", "type": "textarea", "label": "What we relied on instead of asking"}]'::jsonb, array['group', 'communication', 'perspective']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('values-tug-of-war', 'Values Tug of War', 'game'::resource_kind, 'Two players hold a rope, each naming a value they are pulling toward, then debrief the pull.', 'Use it to make the physical feeling of competing values concrete before talking them through.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Give each player one end of a soft rope and one value to hold, such as honesty versus keeping the peace, then let them pull at a comfortable effort for thirty seconds while the group watches. Stop before anyone strains and switch pairs and values each round. The debrief question that matters most is what it felt like to give an inch versus hold firm, and whether that matches how the person handles the real version of that pull.', '[{"id": "f0", "type": "textarea", "label": "The two values in our round"}, {"id": "f1", "type": "textarea", "label": "Which side I pulled"}, {"id": "f2", "type": "textarea", "label": "What holding firm felt like"}, {"id": "f3", "type": "textarea", "label": "What giving an inch felt like"}, {"id": "f4", "type": "textarea", "label": "A real situation this pull reminds me of"}]'::jsonb, array['group', 'values', 'perspective']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('two-minute-partner-interview', 'Two-Minute Partner Interview', 'game'::resource_kind, 'Pairs interview each other for two minutes on a prompt, then introduce their partner to the group.', 'Use it to build a group''s habit of listening for detail instead of preparing what to say next.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Pair people up, give both partners the same prompt card, and time two minutes each way with a visible timer so no one has to guess when to switch. The rule for the introduction round is that each person may only share what their partner told them, not add their own commentary, which keeps the exercise about listening rather than performing. Debrief on what was hard to remember and what it felt like to be introduced by someone else''s words.', '[{"id": "f0", "type": "textarea", "label": "The prompt we used"}, {"id": "f1", "type": "textarea", "label": "What my partner told me"}, {"id": "f2", "type": "textarea", "label": "What I noticed I almost forgot"}, {"id": "f3", "type": "textarea", "label": "How it felt to be introduced in someone else''s words"}, {"id": "f4", "type": "textarea", "label": "One thing I want to remember about my partner"}]'::jsonb, array['group', 'connection', 'listening']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('devils-advocate-debate-cards', 'Devil''s Advocate Debate Cards', 'game'::resource_kind, 'Small teams argue an assigned side of an everyday dilemma, then swap and argue the other side.', 'Use it to loosen a group''s grip on being right by making flexible thinking part of the rules.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Draw an everyday dilemma card — texting an ex, calling out a friend, splitting a bill unevenly — and assign each team a side regardless of what they actually believe. Give three minutes to build the strongest case, then swap sides and argue the opposite. The debrief question to press on is which side was harder to argue and what that says about where a person''s thinking gets stuck, more than which side won.', '[{"id": "f0", "type": "textarea", "label": "The dilemma we debated"}, {"id": "f1", "type": "textarea", "label": "The side I was assigned first"}, {"id": "f2", "type": "textarea", "label": "My strongest point for that side"}, {"id": "f3", "type": "textarea", "label": "What changed when I argued the other side"}, {"id": "f4", "type": "textarea", "label": "Which side was harder to argue, and why"}]'::jsonb, array['group', 'thinking traps', 'perspective']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('mirror-match-warm-up', 'Mirror Match Warm-Up', 'game'::resource_kind, 'Partners silently mirror each other''s slow movements, then switch who is leading.', 'Use it to build a group''s attunement to nonverbal cues before a harder conversation.', array['Groups', 'Teens', 'Adults']::text[], '10 minutes', 'Pair people facing each other and set one clear rule: the leader moves slowly enough that the follower can match in real time, no fast or surprising movements. Switch leaders halfway through without announcing it and see how quickly the pair notices the switch. Debrief on how it felt to lead versus follow and whether the pair matched each other''s pace evenly, since that unevenness often shows up again in how the group talks.', '[{"id": "f0", "type": "textarea", "label": "Who led first in my pair"}, {"id": "f1", "type": "textarea", "label": "How it felt to lead"}, {"id": "f2", "type": "textarea", "label": "How it felt to follow"}, {"id": "f3", "type": "textarea", "label": "When we noticed the switch"}, {"id": "f4", "type": "textarea", "label": "How evenly we matched each other''s pace"}]'::jsonb, array['group', 'mindfulness', 'connection']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('felt-safety-inventory', 'Felt Safety Inventory', 'worksheet'::resource_kind, 'A worksheet that lists the people, places, and sensations that help a client feel safe today.', 'Use it to build a ready list of present-day safety resources for moments when arousal spikes.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep every item anchored in the present, a person, place, or sensation available right now, rather than anything tied to the event itself; if a memory surfaces, gently redirect back to what feels safe in this room. Some clients freeze on the first line, so offer easy prompts like a pet, a blanket, or a doorway in view. Let the list grow slowly across sessions instead of rushing to fill every row in one sitting.', '[{"id": "f0", "type": "textarea", "label": "List three people you feel safe with right now."}, {"id": "f1", "type": "textarea", "label": "List three places where your body feels calmer."}, {"id": "f2", "type": "textarea", "label": "Name a sound, texture, or object that helps you feel grounded."}, {"id": "f3", "type": "textarea", "label": "What is one small thing you could do today to feel a little safer?"}, {"id": "f4", "type": "textarea", "label": "Who could you call or text if things start to feel too big?"}]'::jsonb, array['PTSD and trauma', 'safety', 'grounding', 'support']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('dual-awareness-practice-sheet', 'Dual Awareness Practice Sheet', 'cbt'::resource_kind, 'A CBT worksheet that pairs a present-moment anchor with a felt sense of distress so both can be held at once.', 'Use it to build the client''s capacity to notice activation while staying oriented to the here and now.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk the client through naming one current stressor or body sensation alongside a present-moment anchor, the chair under them, the room''s temperature, a sound nearby, so neither the distress nor the present gets pushed away. This is a stabilization skill, not a review of what happened, so redirect firmly if the client starts narrating the event; keep the focus on right now. Some clients need the anchor named first and the sensation second until the pairing feels steadier.', '[{"id": "f0", "type": "textarea", "label": "What sensation or feeling do you notice in your body right now?"}, {"id": "f1", "type": "textarea", "label": "What is one thing you can see in the room right now?"}, {"id": "f2", "type": "textarea", "label": "What is one thing you can feel with your hands right now (chair, fabric, table)?"}, {"id": "f3", "type": "textarea", "label": "On a scale of 1 to 10, how activated does your body feel right now?"}, {"id": "f4", "type": "textarea", "label": "What helped you feel even slightly more here, in this room?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('safe-enough-activity-ladder', 'Safe Enough Activity Ladder', 'act'::resource_kind, 'An ACT ladder that paces a return to valued activities at whatever speed still feels safe enough.', 'Use it to help the client reconnect with valued activities without pushing faster than their system can tolerate.', array['Adults', 'Teens']::text[], 'One week', 'Have the client list valued activities they have pulled back from since the event, then rank each by how safe enough it currently feels rather than by difficulty alone. The client commits to only the step that still feels manageable this week, and the clinician notes should flag that a stalled rung is information, not failure, so slow the pace rather than pushing through. Nothing here asks for narrative detail about what happened; the focus stays on values and pacing.', '[{"id": "f0", "type": "textarea", "label": "What is one activity you used to enjoy that you have pulled back from?"}, {"id": "f1", "type": "textarea", "label": "On a scale of 1 to 10, how safe enough does trying a small piece of it feel this week?"}, {"id": "f2", "type": "textarea", "label": "What is the smallest version of that activity you could try?"}, {"id": "f3", "type": "textarea", "label": "What value does this activity connect to for you?"}, {"id": "f4", "type": "textarea", "label": "What support would make this step feel more doable?"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing', 'committed action']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('flashback-response-skills-card', 'Flashback Response Skills Card', 'dbt'::resource_kind, 'A pocket card of steps to use the moment a flashback or intrusive memory starts.', 'Use it to give the client a rehearsed sequence for orienting back to the present during an intrusion.', array['Adults', 'Teens']::text[], 'Five minutes', 'Rehearse the sequence in session before the client carries the card: name today''s date and location out loud, name five things they can see, press feet into the floor, and reach for a listed support contact if the intrusion does not ease. This is a stabilization card, not a place to record what the flashback was about, so keep every field oriented to the present moment and to actions. Practice it while calm first so the steps are familiar before they are needed under stress.', '[{"id": "f0", "type": "textarea", "label": "What are three things you can see right now?"}, {"id": "f1", "type": "textarea", "label": "What is today''s date and where are you right now?"}, {"id": "f2", "type": "textarea", "label": "What is one thing you can press your feet or hands against?"}, {"id": "f3", "type": "textarea", "label": "Who is one person you could contact if you need support?"}, {"id": "f4", "type": "textarea", "label": "What is one phrase that helps you feel more in the present, such as ''that was then, this is now''?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('partner-grounding-support-guide', 'Partner Grounding Support Guide', 'couples'::resource_kind, 'A couples worksheet that maps how a partner can help ground the other during a trauma response.', 'Use it to give both partners a shared, rehearsed plan for support in the moment.', array['Couples']::text[], '20 minutes', 'Have the partner who experiences activation name their early signals and what actually helps, while the supporting partner names what they can realistically offer and what to avoid, such as touch without asking first. Meet with both partners together so the plan is agreed rather than assumed, and steer away from any discussion of the event itself; this sheet is about the here-and-now response, not the history behind it. Revisit the plan every few months since signals and needs can shift.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what are your early signs that you are becoming activated?"}, {"id": "f1", "type": "textarea", "label": "Partner one: what specifically helps you feel safer in that moment?"}, {"id": "f2", "type": "textarea", "label": "Partner two: what can you offer when you notice those signs?"}, {"id": "f3", "type": "textarea", "label": "Partner two: what should you check with your partner before doing, such as touch?"}, {"id": "f4", "type": "textarea", "label": "Together: what is one signal or word you can use to ask for this support?"}]'::jsonb, array['PTSD and trauma', 'support', 'grounding', 'relationship issues']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('worry-rocks-backpack', 'Worry Rocks Backpack', 'kids'::resource_kind, 'A craft where a child sorts worry rocks into a backpack to carry and a jar to set down.', 'Use it to help a child physically sort which worries are theirs to carry and which they can set aside.', array['Children']::text[], '20 minutes', 'Have the child decorate a small paper backpack and a jar, then write or draw one worry on each small paper rock. Together sort each rock into the backpack, worries the child can act on today, or the jar, worries that belong to a grown-up or can wait; the parent''s role is to help name which rocks go where without dismissing any worry as silly. Some children want to keep every rock in the backpack at first, so revisit the sort over a few sessions rather than forcing it in one sitting.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one worry on a rock."}, {"id": "f1", "type": "textarea", "label": "Is this worry something you can do something about today?"}, {"id": "f2", "type": "textarea", "label": "Who is a grown-up who could help carry this worry?"}, {"id": "f3", "type": "textarea", "label": "How does your backpack feel now, lighter or the same?"}]'::jsonb, array['anxiety', 'children', 'worry', 'parenting']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('odds-are-dice-game', 'Odds Are Dice Game', 'game'::resource_kind, 'A dice game that compares a feared outcome''s guessed odds with its realistic odds.', 'Use it to build practice estimating real-world probability instead of worst-case certainty.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player names one feared outcome, rolls two dice, and states the number as their gut-feeling percent chance of it happening, then the group discusses a more realistic estimate together and the player rerolls to represent that number instead. Take turns through several rounds, and debrief on how it felt to sit with an estimate lower than the gut reaction. Keep the tone playful; if a player''s fear feels too heavy for the game format, set it aside for individual work instead.', '[{"id": "f0", "type": "textarea", "label": "Name one thing you are worried might happen."}, {"id": "f1", "type": "textarea", "label": "What is your gut-feeling percent chance it happens?"}, {"id": "f2", "type": "textarea", "label": "What is a more realistic percent chance, based on past experience?"}, {"id": "f3", "type": "textarea", "label": "What would you do differently if you believed the realistic number?"}]'::jsonb, array['anxiety', 'uncertainty', 'group']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('what-if-spiral-map', 'What-If Spiral Map', 'worksheet'::resource_kind, 'A worksheet that traces how one what-if thought spirals into the next so a client can find where to step off.', 'Use it to help the client see the spiral''s shape and choose one point to interrupt it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to write their starting what-if thought in the center, then branch out each thought that follows it, arrow by arrow, until the spiral runs its course. Once mapped, review the chain together and mark the earliest point where a different response was possible; that point becomes the target for a coping skill going forward. Some clients find the spiral speeds up as they write, which is useful information about how fast the pattern usually moves.', '[{"id": "f0", "type": "textarea", "label": "Write your starting what-if thought."}, {"id": "f1", "type": "textarea", "label": "What thought came right after that one?"}, {"id": "f2", "type": "textarea", "label": "Keep following the chain, what came next, and next?"}, {"id": "f3", "type": "textarea", "label": "Where in the chain could you have stepped off?"}, {"id": "f4", "type": "textarea", "label": "What is one thing you could do at that point instead?"}]'::jsonb, array['anxiety', 'worry', 'thinking traps']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('probability-overestimation-log', 'Probability Overestimation Log', 'cbt'::resource_kind, 'A CBT log that compares a client''s predicted odds of a feared outcome against what actually happened.', 'Use it to give the client repeated evidence for recalibrating an overestimated probability.', array['Adults', 'Teens']::text[], 'One week', 'Each time a feared prediction comes up, the client logs the predicted percent chance before the event and the actual outcome afterward, building a running record across the week. Review the pattern together in session rather than letting the client draw conclusions alone, since early entries can feel discouraging if the predicted number was high. Watch for clients who quietly skip logging the outcome when the prediction did not come true; that avoidance is itself worth naming.', '[{"id": "f0", "type": "textarea", "label": "What are you predicting will happen?"}, {"id": "f1", "type": "textarea", "label": "What percent chance do you give it before it happens?"}, {"id": "f2", "type": "textarea", "label": "What actually happened?"}, {"id": "f3", "type": "textarea", "label": "How does the predicted number compare to what happened?"}]'::jsonb, array['anxiety', 'thinking traps', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('worry-radio-station-practice', 'Worry Radio Station Practice', 'act'::resource_kind, 'An ACT defusion exercise that reframes anxious thoughts as a radio station playing worst-case broadcasts.', 'Use it to build distance from anxious thoughts so the client can keep acting on their values while the station plays.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client name their anxious inner voice as a radio station, Worry FM or similar, and practice noticing when it switches on without needing to turn it off first. Ask what it is broadcasting today, then ask what the client would do next if the station stayed on in the background rather than in the foreground. This is a noticing practice, not a debate with the content, so redirect gently if the client starts arguing with the broadcast instead of observing it.', '[{"id": "f0", "type": "textarea", "label": "What would you name your worry station?"}, {"id": "f1", "type": "textarea", "label": "What is it broadcasting right now?"}, {"id": "f2", "type": "textarea", "label": "Can you let it play in the background while you do something else?"}, {"id": "f3", "type": "textarea", "label": "What is one thing you''d do next even if the station''s volume stayed the same?"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('build-mastery-step-plan', 'Build Mastery Step Plan', 'dbt'::resource_kind, 'A DBT worksheet that plans one small mastery activity a day to counter low mood.', 'Use it to help the client schedule brief, achievable mastery activities and track the mood shift after each.', array['Adults', 'Teens']::text[], 'One week', 'Draw on the DBT build-mastery skill: help the client pick one small, genuinely achievable task each day, something slightly challenging but not overwhelming, and log mood before and after completing it. Keep the tasks small on purpose; an overambitious goal that fails can reinforce low mood instead of easing it. Watch for clients who plan every task for the end of the week and prompt them to spread attempts across days instead.', '[{"id": "f0", "type": "textarea", "label": "What is one small, doable task for today?"}, {"id": "f1", "type": "textarea", "label": "Rate your mood before starting, 1 to 10."}, {"id": "f2", "type": "textarea", "label": "Rate your mood after finishing, 1 to 10."}, {"id": "f3", "type": "textarea", "label": "What got in the way, if anything?"}, {"id": "f4", "type": "textarea", "label": "What task will you try tomorrow?"}]'::jsonb, array['depression', 'behavioral activation', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('low-mood-support-check-in', 'Low Mood Support Check-In', 'couples'::resource_kind, 'A couples check-in that helps a partner share what low mood feels like today and what support would help.', 'Use it to give both partners a structured way to name needs without one partner guessing or fixing.', array['Couples']::text[], '15 minutes', 'The partner experiencing low mood names their energy level and one concrete thing that would help today, while the supporting partner reflects back what they heard before offering it; this stops well-meant fixing from landing as pressure. Run it as a short, regular check-in rather than only during a hard stretch, so it does not become a crisis-only conversation. Some couples fall into problem-solving too quickly; redirect back to listening first if that happens.', '[{"id": "f0", "type": "textarea", "label": "Partner one: how is your energy today, on a scale of 1 to 10?"}, {"id": "f1", "type": "textarea", "label": "Partner one: what is one thing that would help today?"}, {"id": "f2", "type": "textarea", "label": "Partner two: what did you hear your partner ask for?"}, {"id": "f3", "type": "textarea", "label": "Partner two: what can you offer, realistically, today?"}, {"id": "f4", "type": "textarea", "label": "Together: when will you check in again?"}]'::jsonb, array['depression', 'support', 'communication']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('energy-battery-recharge-chart', 'Energy Battery Recharge Chart', 'kids'::resource_kind, 'A chart where a child colors in their energy battery each day and picks a recharge activity.', 'Use it to help a child notice low-energy days and connect them to one small, chosen activity.', array['Children']::text[], '10 minutes daily', 'Have the child color in a battery icon to show how full or empty they feel that day, then choose one activity from a menu they helped build, a short walk, a favorite song, a game with a parent, to recharge. The parent''s role is to schedule that one activity into the day rather than leaving it to chance, and to color a battery of their own alongside the child so it feels shared rather than singled out. Keep the menu short and revisit it together every couple of weeks.', '[{"id": "f0", "type": "textarea", "label": "Color in how full your battery feels today."}, {"id": "f1", "type": "textarea", "label": "Pick one thing from your recharge menu to try."}, {"id": "f2", "type": "textarea", "label": "Who will help you do it today?"}, {"id": "f3", "type": "textarea", "label": "How full does your battery feel after?"}]'::jsonb, array['depression', 'children', 'routines']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('tiny-wins-toss', 'Tiny Wins Toss', 'game'::resource_kind, 'A toss game where each catch prompts a player to share one tiny win from their week.', 'Use it to build practice noticing small effort and accomplishment that low mood tends to discount.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Players toss a soft ball around the circle; whoever catches it names one tiny win from the past week, no matter how small, getting out of bed on time counts as much as finishing a project. Keep turns quick and resist the urge to rank wins by size, since the point is building the habit of noticing rather than grading the outcome. Debrief by asking what it was like to hear everyone else''s small wins, and whether any of their own surprised them once said aloud.', '[{"id": "f0", "type": "textarea", "label": "What is one tiny win from your week?"}, {"id": "f1", "type": "textarea", "label": "What made that win possible?"}, {"id": "f2", "type": "textarea", "label": "What did it feel like to say it out loud?"}]'::jsonb, array['depression', 'group', 'positive psychology']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('withdrawal-and-return-map', 'Withdrawal and Return Map', 'worksheet'::resource_kind, 'A worksheet that maps activities a client has withdrawn from and one small step back toward each.', 'Use it to turn a long list of dropped activities into a short list of manageable next steps.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list activities they have quietly stopped doing since low mood set in, then, for each one, write the smallest possible version of returning to it rather than the full activity itself. Sort the list by how doable each small step feels right now, and pick only one or two to try before the next session. Clients often list steps that are still too large, so use the session to shrink them further rather than letting an ambitious plan set up another discouraging week.', '[{"id": "f0", "type": "textarea", "label": "What is one activity you''ve pulled back from?"}, {"id": "f1", "type": "textarea", "label": "What is the smallest version of returning to it?"}, {"id": "f2", "type": "textarea", "label": "How doable does that small step feel, 1 to 10?"}, {"id": "f3", "type": "textarea", "label": "What might get in the way?"}, {"id": "f4", "type": "textarea", "label": "What would help you follow through?"}]'::jsonb, array['depression', 'behavioral activation', 'avoidance']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('if-then-plan-builder', 'If-Then Plan Builder', 'cbt'::resource_kind, 'A short worksheet that turns a vague intention into a specific if-then cue the client can act on right away.', 'Use it to help a client turn a stalled intention into an automatic trigger for starting a task.', array['Adults', 'Teens']::text[], '10 minutes', 'This tool is built on implementation intentions: instead of a vague goal like start my report, the client names a specific cue and a specific action, such as when I sit down after coffee I open the document and write one line. Have them write three of these in session and pick the one most likely to happen today. What trips people up is choosing a cue that is not reliably present, like when I feel motivated; push for a fixed time, place, or existing habit instead. Watch for plans stacked onto tasks the client tends to skip entirely.', '[{"id": "f0", "type": "textarea", "label": "Write one task you keep putting off."}, {"id": "f1", "type": "textarea", "label": "Name a cue that happens every day no matter what (a time, place, or habit)."}, {"id": "f2", "type": "textarea", "label": "Write your plan as: When [cue], I will [tiny action]."}, {"id": "f3", "type": "textarea", "label": "Write two backup cues in case the first one doesn''t work."}, {"id": "f4", "type": "textarea", "label": "What usually gets in the way of starting?"}]'::jsonb, array['ADHD', 'behavioral', 'habits', 'planning']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('values-over-urgency-sort', 'Values Over Urgency Sort', 'act'::resource_kind, 'A sorting exercise that separates tasks pulling for attention from the ones that actually matter to the client.', 'Use it to help a client notice when urgency is driving their day instead of their own values.', array['Adults', 'Teens']::text[], '20 minutes', 'The client lists everything competing for attention on a typical day, then sorts each item into loud and urgent or quiet and valued, noticing how often the loud pile wins even when the quiet pile matters more. In session, ask what it costs when a valued task keeps losing to a louder one. What trips people up is confusing urgency with importance; a notification and a values-linked task can both feel pressing in the body, so slow the client down to check which one actually connects to something they care about. Some clients need a shorter list to avoid overwhelm.', '[{"id": "f0", "type": "textarea", "label": "List everything pulling for your attention on a typical day."}, {"id": "f1", "type": "textarea", "label": "Circle the ones that feel loud and urgent, even if they don''t matter much."}, {"id": "f2", "type": "textarea", "label": "Underline the ones that feel quiet but connect to something you value."}, {"id": "f3", "type": "textarea", "label": "Pick one quiet, valued task to protect tomorrow."}, {"id": "f4", "type": "textarea", "label": "What usually happens when you try to protect it?"}]'::jsonb, array['ADHD', 'values', 'attention', 'committed action']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('one-mindfully-task-card', 'One-Mindfully Task Card', 'dbt'::resource_kind, 'A pocket card that walks a client through doing one task at a time when attention keeps splitting.', 'Use it to help a client practice the one-mindfully skill on a single task instead of several at once.', array['Adults', 'Teens']::text[], '5 minutes', 'The card gives the client three prompts for a task: name the one thing you are doing, notice when attention has moved elsewhere, and gently bring it back without self-criticism. Practice it in session on something boring, like folding a napkin, so the client feels the pull to multitask and the return in real time. What trips people up is expecting attention to stay put; the skill is the returning, not the staying, so normalize needing to return many times in one task. Keep the card visible, like on a desk or a phone lock screen.', '[{"id": "f0", "type": "textarea", "label": "Name the one task you are about to do."}, {"id": "f1", "type": "textarea", "label": "Set a short timer and start the task."}, {"id": "f2", "type": "textarea", "label": "When your mind wanders, write down where it went."}, {"id": "f3", "type": "textarea", "label": "Bring your attention back to the task without judging yourself."}, {"id": "f4", "type": "textarea", "label": "How many times did you notice your attention move?"}]'::jsonb, array['ADHD', 'mindfulness', 'attention', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('task-handoff-agreement', 'Task Handoff Agreement', 'couples'::resource_kind, 'A short agreement that spells out how one partner hands a task to the other without it getting lost.', 'Use it to help both partners agree on a clear handoff instead of relying on memory alone.', array['Couples']::text[], '15 minutes', 'One partner often carries tasks in their head and forgets them mid-stream, while the other ends up frustrated by dropped follow-through; this agreement has both partners name one task being handed over, write what done looks like, and agree on a specific place it gets written down so neither is relying on memory. Run it in session so each partner hears how a missed handoff lands before it becomes a blame conversation at home. What trips people up is a vague handoff like can you deal with the mail; push for a concrete finish line and a day. Revisit the agreement after a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: name one task you are handing over."}, {"id": "f1", "type": "textarea", "label": "Partner A: what does finished look like?"}, {"id": "f2", "type": "textarea", "label": "Partner B: where will you write this down so you don''t forget?"}, {"id": "f3", "type": "textarea", "label": "Both: by when will it be done?"}, {"id": "f4", "type": "textarea", "label": "Both: how will you check in without it feeling like a reminder?"}]'::jsonb, array['ADHD', 'communication', 'planning']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('body-battery-check-in-chart', 'Body Battery Check-In Chart', 'kids'::resource_kind, 'A drawn battery icon a child colors in to show how much focus and energy they have left.', 'Use it to help a child notice and name a dropping attention battery before it hits empty.', array['Children']::text[], '10 minutes', 'The child draws a battery icon and colors it in to match how full their focus feels right now, then the parent helps them name what usually drains it, like a loud room or a long worksheet, and what recharges it, like a movement break or a snack. Use simple, playful language and let the child pick their own colors and stickers. What trips people up is waiting until the battery reads empty to check in; coach the parent to ask for a check partway through homework, before frustration builds. Post the chart where the child can point to it instead of explaining in words.', '[{"id": "f0", "type": "textarea", "label": "Draw your battery and color in how full it feels right now."}, {"id": "f1", "type": "textarea", "label": "What usually makes your battery go down fast?"}, {"id": "f2", "type": "textarea", "label": "What helps your battery fill back up?"}, {"id": "f3", "type": "textarea", "label": "Draw a picture of your favorite recharge break."}, {"id": "f4", "type": "textarea", "label": "Show a grown-up your battery today and tell them the number."}]'::jsonb, array['ADHD', 'children', 'art', 'self-monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('urge-countdown-game', 'Urge Countdown Game', 'game'::resource_kind, 'A quick card game where players race to name a coping move before an urge''s clock runs out.', 'Use it to give a client fast practice matching an urge to a ready response before it fades or peaks.', array['Adults', 'Groups']::text[], '20 minutes', 'Deal each player a card naming a common urge trigger, like boredom, a stressful call, or a specific place, and set a short timer for how long an urge typically holds before it eases; the player names a coping move out loud before time runs out, and the group can add options if stuck. Play several rounds, then debrief on which coping moves came to mind fastest and which triggers left the group blank. What trips people up is treating this as a quiz with one right answer; any response works as long as it does not involve substance use. Keep the tone light, not like a test.', '[{"id": "f0", "type": "textarea", "label": "Write one urge trigger that shows up often for you."}, {"id": "f1", "type": "textarea", "label": "Write the coping move you reached for fastest during the game."}, {"id": "f2", "type": "textarea", "label": "Write a trigger that left you stuck, with no ready response."}, {"id": "f3", "type": "textarea", "label": "Name one new coping move you heard from someone else that you''d try."}, {"id": "f4", "type": "textarea", "label": "Where will you keep this list so it''s handy when an urge shows up?"}]'::jsonb, array['addiction', 'urges', 'group', 'coping skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('high-risk-moment-map', 'High-Risk Moment Map', 'worksheet'::resource_kind, 'A worksheet that maps the times, places, and people linked to a rise in urges around substance use.', 'Use it to help a client see the pattern behind their highest-risk moments instead of feeling ambushed by them.', array['Adults']::text[], '20 minutes', 'The client fills in a grid crossing time of day, place, and who they were with for the last several moments an urge toward substance use spiked, then looks for repeats: a certain hour, an empty apartment, a specific friend. In session, ask what was happening emotionally in the hour before each moment, not just the moment itself, since urges build before they peak. What trips people up is listing only dramatic triggers and skipping quieter ones, like a slow afternoon with nothing planned; prompt for one low-key moment too. Use the map to plan around the riskiest windows, not willpower alone.', '[{"id": "f0", "type": "textarea", "label": "List the last few times an urge to use spiked."}, {"id": "f1", "type": "textarea", "label": "For each one, write the time of day and where you were."}, {"id": "f2", "type": "textarea", "label": "For each one, write who you were with, if anyone."}, {"id": "f3", "type": "textarea", "label": "What was happening in the hour before each spike?"}, {"id": "f4", "type": "textarea", "label": "Which time, place, or person shows up more than once?"}, {"id": "f5", "type": "textarea", "label": "What''s one change you could make around your riskiest window?"}]'::jsonb, array['addiction', 'urges', 'triggers', 'self-monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('urge-intensity-timeline', 'Urge Intensity Timeline', 'cbt'::resource_kind, 'A tracking sheet that graphs how an urge''s intensity rises and falls across its course.', 'Use it to help a client see that an urge has a shape and an end, not a flat, unbroken pull.', array['Adults']::text[], '15 minutes', 'Across a week, the client rates the intensity of urges tied to substance use on a zero-to-ten scale at set check-in points, whether or not they act on the urge, and plots the numbers to see the rise and fall rather than assuming it only climbs. Review the timeline together, pointing out the peak, how long it lasted, and the number twenty minutes later. What trips people up is checking in only during the worst moments, which makes urges look constant; ask for at least one calm-stretch rating too. Use the pattern to set realistic expectations for how long a client needs to ride out a spike.', '[{"id": "f0", "type": "textarea", "label": "Rate your urge from zero to ten right now."}, {"id": "f1", "type": "textarea", "label": "Write what''s happening around you at this moment."}, {"id": "f2", "type": "textarea", "label": "Rate the same urge again in twenty minutes."}, {"id": "f3", "type": "textarea", "label": "What did you do while you waited it out?"}, {"id": "f4", "type": "textarea", "label": "Looking at today''s numbers, when was the peak?"}]'::jsonb, array['addiction', 'urges', 'self-monitoring', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('room-for-the-urge-practice', 'Room for the Urge Practice', 'act'::resource_kind, 'A short practice that has a client make space for an urge in their body instead of pushing it away.', 'Use it to help a client hold an urge without fighting it or immediately acting on it.', array['Adults']::text[], '10 minutes', 'Guide the client to notice where an urge tied to substance use shows up in the body, then, instead of tensing against it, have them breathe into that spot and imagine making room around it, the way you''d loosen a tight collar rather than pull it off. Say the urge''s name softly, like there''s an urge here right now, to build a gap between noticing it and acting on it. What trips people up is expecting the urge to vanish; the aim is coexisting with it a while, not eliminating it, so name that beforehand. Practice on a mild everyday urge first, like reaching for a phone, before a stronger one.', '[{"id": "f0", "type": "textarea", "label": "Where in your body do you notice the urge?"}, {"id": "f1", "type": "textarea", "label": "Describe its size, shape, or temperature."}, {"id": "f2", "type": "textarea", "label": "Say silently: there''s an urge here, and I don''t have to act on it."}, {"id": "f3", "type": "textarea", "label": "Breathe into that spot for five slow breaths."}, {"id": "f4", "type": "textarea", "label": "What did you notice change, if anything?"}]'::jsonb, array['addiction', 'urges', 'acceptance', 'willingness']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('urge-delay-card', 'Urge Delay Card', 'dbt'::resource_kind, 'A pocket card that walks a client through delaying action on an urge in fifteen-minute steps.', 'Use it to give a client a concrete way to put distance between an urge and a decision.', array['Adults']::text[], '5 minutes', 'The card sets a fifteen-minute delay before the client acts on an urge tied to substance use, backed by a short list of distraction and soothing moves picked in session, like calling a support person, stepping outside, or running cold water over their hands. When the timer ends, the client rechecks the urge''s intensity and either rides out fifteen more minutes or moves to a next step. What trips people up is picking distractions not actually available, like a hobby needing setup; keep the list short and reachable in under a minute. Practice picking an option before the client leaves.', '[{"id": "f0", "type": "textarea", "label": "Write three things you can do in under a minute to distance yourself."}, {"id": "f1", "type": "textarea", "label": "Write the name and number of one support person to call."}, {"id": "f2", "type": "textarea", "label": "Set a fifteen-minute timer and try one option."}, {"id": "f3", "type": "textarea", "label": "Rate the urge again once the timer ends."}, {"id": "f4", "type": "textarea", "label": "What''s your next step: another fifteen minutes, or calling your support person?"}]'::jsonb, array['addiction', 'urges', 'distress tolerance', 'support']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('anger-signals-check-in', 'Anger Signals Check-In', 'couples'::resource_kind, 'A short conversation guide where partners share their own early anger signals with each other.', 'Use it to help both partners recognize the other''s early warning signs before anger escalates.', array['Couples']::text[], '20 minutes', 'Each partner separately names the physical and behavioral signs that show up before they get angry, like a tight jaw, going quiet, or talking faster, then the couple shares lists in session so both can start spotting the signal instead of only the blowup. Ask each partner what they''d want the other to do when they notice it, whether that''s naming it gently or giving space. What trips people up is one partner using the list as ammunition later; frame it as information for care, not a scorecard. Have the couple keep both lists somewhere they can glance at during a tense moment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what does your body do right before you get angry?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what do you want your partner to do when they see that?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what does your body do right before you get angry?"}, {"id": "f3", "type": "textarea", "label": "Partner B: what do you want your partner to do when they see that?"}, {"id": "f4", "type": "textarea", "label": "Both: what''s one signal you never noticed in the other before today?"}]'::jsonb, array['anger management', 'communication', 'de-escalation']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('mad-monster-mask-craft', 'Mad Monster Mask Craft', 'kids'::resource_kind, 'A child decorates a paper mask as their mad monster, then talks about what wakes it up and calms it down.', 'Use it to give a child a playful, external character for talking about anger without feeling blamed.', array['Children']::text[], '25 minutes', 'The child draws and decorates a mask for their mad monster, choosing a face, colors, and a name, then the parent asks what wakes the monster up, what it wants to do when it''s awake, and what helps it fall back asleep. Keeping the anger in the monster gives the child room to describe big feelings without feeling like they are the problem. What trips people up is a parent rushing to correct the child''s description; let the story unfold first and save coaching for after the mask is finished. Keep the mask visible at home as a shared reference next time the monster shows up.', '[{"id": "f0", "type": "textarea", "label": "Draw and decorate your mad monster''s face."}, {"id": "f1", "type": "textarea", "label": "Give your monster a name."}, {"id": "f2", "type": "textarea", "label": "What wakes your monster up?"}, {"id": "f3", "type": "textarea", "label": "What does your monster want to do when it''s awake?"}, {"id": "f4", "type": "textarea", "label": "What helps your monster calm down and go back to sleep?"}]'::jsonb, array['anger management', 'children', 'art', 'externalizing']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('cool-down-card-race', 'Cool-Down Card Race', 'game'::resource_kind, 'A turn-based card game where players race through a set of cool-down steps before time runs out.', 'Use it to give a client or group repeated, low-stakes practice moving through cool-down steps quickly.', array['Teens', 'Groups']::text[], '20 minutes', 'Shuffle a deck of cards, each naming one cool-down step like naming the feeling, three slow breaths, or stepping away, and give each player a scenario card describing a moment that would spark anger; on their turn, a player draws cool-down cards and acts out each step against a short timer, racing to reach the last card before time runs out. Debrief on which steps felt easiest and which ones players wanted to skip. What trips people up is players rushing through steps without doing them; slow the pace and model one round yourself first. Keep scenario cards realistic to the group''s own life.', '[{"id": "f0", "type": "textarea", "label": "Write the anger scenario your card described."}, {"id": "f1", "type": "textarea", "label": "List the cool-down steps in the order you used them."}, {"id": "f2", "type": "textarea", "label": "Which step was hardest to actually do, not just say?"}, {"id": "f3", "type": "textarea", "label": "Which step do you think you''d reach for first in real life?"}, {"id": "f4", "type": "textarea", "label": "What would make that step easier to remember in the moment?"}]'::jsonb, array['anger management', 'group', 'de-escalation', 'coping skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('anger-fuel-and-fizzle-log', 'Anger Fuel and Fizzle Log', 'worksheet'::resource_kind, 'A log that tracks what feeds an angry moment and what helps it fizzle out afterward.', 'Use it to help a client separate what fuels their anger from what actually cools it down.', array['Adults', 'Teens']::text[], '15 minutes', 'After an anger episode, the client logs what fueled it, like being interrupted or feeling dismissed, and separately logs what helped it fizzle, whether that was walking away, a text to a friend, or time passing. Over several entries, patterns surface: the same fuel showing up repeatedly, or a fizzle strategy that works more reliably than expected. What trips people up is logging only the fuel and skipping the fizzle, since that side often gets forgotten once the moment has passed; prompt for it the same day. Review the log every couple of weeks to sort out which fizzle strategies work.', '[{"id": "f0", "type": "textarea", "label": "What happened right before you noticed anger building?"}, {"id": "f1", "type": "textarea", "label": "What fueled it, in your own words?"}, {"id": "f2", "type": "textarea", "label": "What did you do once you noticed it?"}, {"id": "f3", "type": "textarea", "label": "What actually helped it fizzle out?"}, {"id": "f4", "type": "textarea", "label": "Looking back, what fuel keeps showing up across entries?"}]'::jsonb, array['anger management', 'triggers', 'self-monitoring', 'coping skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('hostile-read-thought-check', 'Hostile Read Thought Check', 'cbt'::resource_kind, 'A quick check that tests a client''s first hostile read of someone else''s action against other explanations.', 'Use it to help a client slow down an automatic hostile interpretation before it fuels anger.', array['Adults', 'Teens']::text[], '10 minutes', 'When a client describes getting angry at someone''s action, like being cut off in traffic or not getting a text back, have them write the automatic read first, usually something like they did that on purpose, then generate two other explanations that fit the same facts. Rate how believable each explanation feels and notice whether the anger shifts as the client works through the list. What trips people up is generating alternatives that still carry blame; push for one explanation that has nothing to do with the client at all. Practice on a recent lower-stakes moment before a harder one.', '[{"id": "f0", "type": "textarea", "label": "What did the other person do?"}, {"id": "f1", "type": "textarea", "label": "What was your first read on why they did it?"}, {"id": "f2", "type": "textarea", "label": "Write two other explanations that fit the same facts."}, {"id": "f3", "type": "textarea", "label": "Rate how believable each explanation feels, zero to ten."}, {"id": "f4", "type": "textarea", "label": "Did your anger shift as you worked through the list?"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT', 'automatic thoughts']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('certainty-trap-metaphor', 'The Certainty Trap Metaphor', 'act'::resource_kind, 'A metaphor exercise for the pull to grip harder at certainty about an intrusive thought.', 'Use it to build willingness to sit with doubt instead of chasing certainty.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce the trap metaphor before the exercise: the harder a client grips at certainty about an intrusive thought, the tighter the trap seems to close, the way wet sand squeezes through a clenched fist. Walk through moments the client notices themselves gripping, such as checking, asking or reviewing, and what loosening the grip could look like for even a few seconds. Some clients resist at first because letting go feels like giving in to the doubt; go slow and stay curious about that fear with them.', '[{"id": "f0", "type": "textarea", "label": "Where does the urge to grip for certainty show up most in your week?"}, {"id": "f1", "type": "textarea", "label": "What does ''gripping tighter'' look like for you — checking, asking, reviewing?"}, {"id": "f2", "type": "textarea", "label": "Describe a moment you loosened your grip on certainty, even briefly."}, {"id": "f3", "type": "textarea", "label": "What did you notice in your body or mind when you loosened your grip?"}, {"id": "f4", "type": "textarea", "label": "What is one place this week you could practice loosening the grip on purpose?"}]'::jsonb, array['OCD', 'metaphor', 'willingness', 'uncertainty']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('compulsion-opposite-action-plan', 'Compulsion Opposite Action Plan', 'dbt'::resource_kind, 'A plan for practicing DBT''s opposite action skill against a specific compulsive urge.', 'Use it to help a client rehearse acting opposite to an urge to check, wash or repeat.', array['Adults', 'Teens']::text[], '15 minutes plus daily practice', 'Have the client name one recurring urge — to check, wash, count or repeat — and describe the action the urge is pushing toward. Together define the opposite action: staying with the unlocked door, the imperfect email, the unwashed hands a little longer than feels tolerable. Rehearse the opposite action in session first when possible, then log real attempts through the week. Watch for the client quietly adding a mental compulsion, like silently repeating a phrase, in place of the physical one, and name that pattern if it shows up.', '[{"id": "f0", "type": "textarea", "label": "Name the urge you are working with this week."}, {"id": "f1", "type": "textarea", "label": "What is the urge pushing you to do?"}, {"id": "f2", "type": "textarea", "label": "What is the opposite action, in specific and doable terms?"}, {"id": "f3", "type": "textarea", "label": "How did the opposite action go when you tried it?"}, {"id": "f4", "type": "textarea", "label": "What got in the way, if anything, and what would help next time?"}]'::jsonb, array['OCD', 'urges', 'distress tolerance']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-response-plan', 'Partner Reassurance Response Plan', 'couples'::resource_kind, 'A plan for how a partner responds to reassurance requests without feeding the cycle.', 'Use it to help both partners agree on a kinder way to answer reassurance-seeking.', array['Couples']::text[], '30 minutes', 'The requesting partner names the questions and reassurance-seeking they lean on most, and the other partner names how often they currently answer them and what that costs. Together they draft a short, warm script the answering partner can use instead of repeating the reassurance, along with a signal the requesting partner can give when the urge feels hardest to sit with. This works best introduced gradually rather than as an overnight switch, and the answering partner may need coaching on how to stay warm while still holding the new response.', '[{"id": "f0", "type": "textarea", "label": "What questions or reassurance do you ask your partner most often?"}, {"id": "f1", "type": "textarea", "label": "Partner: how do you usually respond, and how does that leave you feeling afterward?"}, {"id": "f2", "type": "textarea", "label": "Draft the new short response your partner will use instead."}, {"id": "f3", "type": "textarea", "label": "What signal will you give each other when the urge to ask or answer is strongest?"}, {"id": "f4", "type": "textarea", "label": "What would make it easier to stick with this plan on a hard day?"}]'::jsonb, array['OCD', 'couples', 'communication']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('doubt-detective-badge-craft', 'Doubt Detective Badge Craft', 'kids'::resource_kind, 'A badge-making craft that casts a child as a detective who questions sneaky doubts.', 'Use it to give a child a playful role for noticing and questioning intrusive doubts.', array['Children']::text[], '30 minutes', 'The child decorates a paper badge and names their detective persona, then draws or writes three clues, doubts that show up and try to trick them into checking or asking again. The parent helps the child practice a detective line, such as ''that doubt is not new evidence,'' and wears the badge during a practice moment at home that week. Keep the tone playful rather than serious; the point is distance from the doubt, not winning an argument with it.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one doubt your detective badge is watching for."}, {"id": "f1", "type": "textarea", "label": "What does this doubt try to get you to do?"}, {"id": "f2", "type": "textarea", "label": "What is your detective line for talking back to the doubt?"}, {"id": "f3", "type": "textarea", "label": "Parent: when did you see your detective use the badge this week?"}, {"id": "f4", "type": "textarea", "label": "What happened when the doubt got a detective line instead of a checking trip?"}]'::jsonb, array['OCD', 'children', 'externalizing', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('doubt-or-fact-card-sort', 'Doubt or Fact Card Sort', 'game'::resource_kind, 'A turn-based sorting game that separates sticky doubts from plain facts.', 'Use it to build a light, shared vocabulary for spotting doubt versus fact in session.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Write a mix of statements on cards, some plain facts, some sticky doubts dressed up as facts, and shuffle the deck. Players take turns drawing a card, reading it aloud, and sorting it into a doubt or fact pile before the group votes; a correct guess earns a point, and a debate over a tricky card is where the real work happens. Close with a short debrief on which cards were hardest to sort and why doubts are built to feel convincing.', '[{"id": "f0", "type": "textarea", "label": "Write one statement that felt like a fact but turned out to be a doubt."}, {"id": "f1", "type": "textarea", "label": "What made that doubt so convincing in the moment?"}, {"id": "f2", "type": "textarea", "label": "Which card was hardest for the group to sort, and why?"}, {"id": "f3", "type": "textarea", "label": "What helps you tell a doubt from a fact outside of the game?"}]'::jsonb, array['OCD', 'thinking traps', 'group']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('after-the-panic-debrief-sheet', 'After the Panic Debrief Sheet', 'worksheet'::resource_kind, 'A short debrief a client fills out once a panic episode has passed.', 'Use it to review what preceded a panic episode and what helped it ease.', array['Adults', 'Teens']::text[], '10 minutes', 'Fill this out with the client once the acute spike has passed, either in session or as soon after an episode as the client can manage. It separates what came before the episode from what the client tried during it and what actually seemed to help, so patterns become visible across several entries rather than staying a single blurry memory. Clients often underestimate how much already helped; point that out when the sheet shows it.', '[{"id": "f0", "type": "textarea", "label": "What were you doing right before the episode started?"}, {"id": "f1", "type": "textarea", "label": "What did you notice first in your body?"}, {"id": "f2", "type": "textarea", "label": "What did you try while it was happening?"}, {"id": "f3", "type": "textarea", "label": "What seemed to help it ease, even a little?"}, {"id": "f4", "type": "textarea", "label": "What would you want to remember for next time?"}]'::jsonb, array['panic attacks', 'monitoring', 'self-monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('fear-of-fear-prediction-log', 'Fear of Fear Prediction Log', 'cbt'::resource_kind, 'A log that tracks predictions about panic sensations against what actually happens.', 'Use it to loosen the fear-of-fear cycle by testing predictions against outcomes.', array['Adults', 'Teens']::text[], 'Five minutes per entry over two weeks', 'Panic often keeps itself going through a second layer of fear about the sensations themselves, the sense that a racing heart means something is badly wrong. Have the client write the exact prediction before a sensation escalates, rate how convinced they are, then log what actually happened once it passed. Reviewing several entries side by side, in session, tends to do more than any single one; watch for predictions getting vaguer over time as a sign the client is avoiding pinning them down.', '[{"id": "f0", "type": "textarea", "label": "What sensation are you noticing right now?"}, {"id": "f1", "type": "textarea", "label": "What do you predict will happen if it keeps going?"}, {"id": "f2", "type": "textarea", "label": "How convinced are you of that prediction, from 0 to 100?"}, {"id": "f3", "type": "textarea", "label": "What actually happened once the sensation passed?"}, {"id": "f4", "type": "textarea", "label": "How does the outcome compare with the prediction?"}]'::jsonb, array['panic attacks', 'thinking traps', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('staying-in-the-storm-practice', 'Staying in the Storm Practice', 'act'::resource_kind, 'A willingness practice for staying present through a panic surge rather than fleeing it.', 'Use it to build willingness to stay in a situation while panic sensations move through.', array['Adults', 'Teens']::text[], '15 minutes', 'Introduce the storm as a metaphor for a panic surge: it builds, peaks and passes on its own timeline, and the client''s job is not to stop the storm but to stay standing through it. Practice naming the urge to leave, run or fight the sensations the moment it shows up, and choosing one small willing action instead, like keeping both feet still. This is easiest to build gradually in low-stakes moments before asking a client to try it during a full episode.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent moment the panic ''storm'' started building."}, {"id": "f1", "type": "textarea", "label": "What was the urge telling you to do — leave, fight, distract?"}, {"id": "f2", "type": "textarea", "label": "What is one small willing action you could take instead of following the urge?"}, {"id": "f3", "type": "textarea", "label": "What did you notice about the storm''s shape — building, peak, passing?"}, {"id": "f4", "type": "textarea", "label": "What would staying a little longer make possible for you?"}]'::jsonb, array['panic attacks', 'willingness', 'acceptance']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('panic-reset-temperature-card', 'Panic Reset Temperature Card', 'dbt'::resource_kind, 'A pocket card walking a client through a cold-temperature reset during a panic spike.', 'Use it to give a client a fast physical reset to try when a panic spike feels overwhelming.', array['Adults', 'Teens']::text[], 'Five minutes', 'Cold water or an ice pack held to the face can shift the body''s alarm response quickly during a sharp panic spike, and this card walks a client through the steps in order: where to hold the cold, how long, and what to expect as the surge starts to settle. Practice the steps in session so the sequence is familiar before a real spike, and check for any heart condition or other reason cold exposure would not be a fit before assigning it as homework.', '[{"id": "f0", "type": "textarea", "label": "Where will you keep cold water or an ice pack accessible?"}, {"id": "f1", "type": "textarea", "label": "Walk through the steps you will take when a spike starts."}, {"id": "f2", "type": "textarea", "label": "What did you notice in your body during and after using the card?"}, {"id": "f3", "type": "textarea", "label": "How long did it take for the spike to settle?"}, {"id": "f4", "type": "textarea", "label": "What would make this easier to reach for next time?"}]'::jsonb, array['panic attacks', 'distress tolerance', 'grounding']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-cycle-map', 'Partner Reassurance Cycle Map', 'couples'::resource_kind, 'A map of how a partner''s reassurance during panic keeps the cycle going for both of them.', 'Use it to help a couple see and shift a reassurance pattern built up around panic episodes.', array['Couples']::text[], '30 minutes', 'Draw the cycle together: the panicking partner''s request for reassurance, the supporting partner''s response, the short-term relief, and how the same request tends to return sooner and louder next time. Naming the pattern out loud often brings relief and some defensiveness at once, since the supporting partner has usually been doing what looked most caring. Close by drafting one small shift each partner is willing to try, such as a pause before answering or a shorter response.', '[{"id": "f0", "type": "textarea", "label": "What does the request for reassurance usually sound like?"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what do you usually say or do in response?"}, {"id": "f2", "type": "textarea", "label": "How long does the relief tend to last before the request returns?"}, {"id": "f3", "type": "textarea", "label": "What is one small shift you are each willing to try?"}, {"id": "f4", "type": "textarea", "label": "What support would make that shift easier to hold to?"}]'::jsonb, array['panic attacks', 'reassurance seeking', 'relationship issues']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('family-feelings-check-in-wheel', 'Family Feelings Check-In Wheel', 'kids'::resource_kind, 'A spinning wheel craft the family points to for a quick feelings check-in together.', 'Use it to build a quick, low-pressure habit of naming feelings as a family.', array['Children', 'Adults']::text[], '30 minutes to build, then a few minutes daily', 'The child decorates a paper wheel with feeling faces and a spinning arrow while the parent builds a matching one, and the family picks a daily moment, such as dinner, to each point to how they are feeling before talking about why. The parent''s job is to model naming a hard feeling plainly, including their own, since children tend to match whatever level of honesty the adults show first. Keep entries short on busy nights rather than skipping the check-in altogether.', '[{"id": "f0", "type": "textarea", "label": "Draw or write the feelings on your wheel."}, {"id": "f1", "type": "textarea", "label": "Point to how you are feeling right now."}, {"id": "f2", "type": "textarea", "label": "What is one reason you feel that way today?"}, {"id": "f3", "type": "textarea", "label": "Parent: what feeling did you point to, and what made that true today?"}, {"id": "f4", "type": "textarea", "label": "What was it like to hear how someone else in the family was feeling?"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('special-time-roll-and-play', 'Special Time Roll and Play', 'game'::resource_kind, 'A roll-and-play dice game that turns one-on-one special time into a set of connection prompts.', 'Use it to make regular one-on-one time easy to start and hard to skip.', array['Adults', 'Children']::text[], '15 minutes', 'Build a simple die or spinner labeled with six connection activities, a silly voice game, a drawing challenge, a pillow fort minute, and similar low-prep options, and let the child roll to pick what special time looks like that day. The parent''s only rule during the roll is to follow the child''s lead on the activity without correcting or directing it, even when the drawing is messy or the rules keep changing. End with a short debrief on what each of you liked best.', '[{"id": "f0", "type": "textarea", "label": "What did you roll, and what did you choose to play?"}, {"id": "f1", "type": "textarea", "label": "Parent: what was hardest about following your child''s lead today?"}, {"id": "f2", "type": "textarea", "label": "Child: what was your favorite part of special time today?"}, {"id": "f3", "type": "textarea", "label": "What would you want to roll again next time?"}]'::jsonb, array['parenting', 'connection', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('positive-to-corrective-ratio-tracker', 'Positive to Corrective Ratio Tracker', 'worksheet'::resource_kind, 'A daily tally of positive attention against corrective comments a parent gives a child.', 'Use it to help a parent notice and shift the balance of positive to corrective attention.', array['Adults']::text[], 'A few minutes daily for one week', 'Most parents estimate their ratio of praise to correction far more generously than a tally shows, so have the parent make simple hash marks through the day rather than trying to recall totals at night. A lopsided count is common and not a verdict on the parent; use it to find one or two moments a day where a specific, genuine positive comment could fit naturally. Revisit the tally weekly rather than daily so small shifts have room to show up.', '[{"id": "f0", "type": "textarea", "label": "Tally each positive comment you gave today."}, {"id": "f1", "type": "textarea", "label": "Tally each corrective comment you gave today."}, {"id": "f2", "type": "textarea", "label": "What is one moment today a positive comment could have fit?"}, {"id": "f3", "type": "textarea", "label": "What got in the way of noticing positives in the moment?"}, {"id": "f4", "type": "textarea", "label": "What is one specific positive comment you will look for tomorrow?"}]'::jsonb, array['parenting', 'praise', 'monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('parent-guilt-thought-record', 'Parent Guilt Thought Record', 'cbt'::resource_kind, 'A thought record for the guilt-driven thoughts that follow a hard parenting moment.', 'Use it to help a parent examine guilt thoughts rather than simply carrying them.', array['Adults']::text[], '15 minutes', 'Have the parent write the exact thought that followed a hard moment, snapping, missing a school event, losing patience, word for word rather than the general feeling of guilt. Walk through the evidence for and against the thought as written, and a more balanced version that still takes the moment seriously without inflating it into a verdict on the parent''s whole character. Watch for the balanced thought sliding back into a harsher one by the next line; that slide is often the most useful part to discuss.', '[{"id": "f0", "type": "textarea", "label": "What is the exact guilt thought, word for word?"}, {"id": "f1", "type": "textarea", "label": "What moment brought it on?"}, {"id": "f2", "type": "textarea", "label": "What evidence supports the thought?"}, {"id": "f3", "type": "textarea", "label": "What evidence works against the thought as written?"}, {"id": "f4", "type": "textarea", "label": "Write a more balanced version of the thought."}]'::jsonb, array['parenting', 'guilt', 'thinking traps']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('parent-i-want-to-be-compass', 'The Parent I Want to Be Compass', 'act'::resource_kind, 'A values exercise mapping the kind of parent a client wants to be against a hard week.', 'Use it to reconnect a parent with chosen values after a week that felt off course.', array['Adults']::text[], '20 minutes', 'Ask the parent to describe, in their own words, the kind of parent they want to be, warm, steady, playful, whatever fits, before looking at a specific recent moment that felt far from that. The gap is not evidence of failure; it is information about where a small committed action could point back toward the compass this week. Keep the chosen action small and concrete, since parents in this exercise tend to reach for something too large to sustain.', '[{"id": "f0", "type": "textarea", "label": "In your own words, what kind of parent do you want to be?"}, {"id": "f1", "type": "textarea", "label": "Describe a recent moment that felt far from that."}, {"id": "f2", "type": "textarea", "label": "What got in the way in that moment?"}, {"id": "f3", "type": "textarea", "label": "What is one small action this week that points back toward your compass?"}, {"id": "f4", "type": "textarea", "label": "What would help you remember this compass in a hard moment?"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-birth-you-had', 'Radical Acceptance for the Birth You Had', 'dbt'::resource_kind, 'A DBT worksheet guiding a new parent through radically accepting a birth that didn''t go as planned.', 'Use it to help a client stop fighting a birth experience they can''t change.', array['Adults']::text[], '20 minutes', 'Walk the client through the steps of radical acceptance applied specifically to their birth experience: naming what happened, noticing where they are still arguing with reality, and practicing turning the mind toward acceptance without implying they have to approve of what happened. This tends to surface grief, anger, or guilt about interventions, a birth plan that changed, or feeling unheard by a care team, so pace it slowly and expect more than one pass. Watch for a client who equates acceptance with saying the birth was fine; the point is ending the internal fight, not endorsing it.', '[{"id": "f0", "type": "textarea", "label": "What did you picture your birth being like, before it happened?"}, {"id": "f1", "type": "textarea", "label": "What actually happened, in your own words?"}, {"id": "f2", "type": "textarea", "label": "What part of it are you still arguing with or wishing you could redo?"}, {"id": "f3", "type": "textarea", "label": "What would it feel like to stop fighting that part, even for one minute?"}, {"id": "f4", "type": "textarea", "label": "What do you still need to grieve about how it went?"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'grief and loss', 'birth']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('postpartum-intimacy-reconnection-guide', 'Postpartum Intimacy Reconnection Guide', 'couples'::resource_kind, 'A conversation guide that helps new parents talk through changes to physical and emotional intimacy after birth.', 'Use it to open a low-pressure conversation about intimacy before it becomes a silent sore spot.', array['Couples']::text[], '30 minutes', 'Have each partner complete their half before talking, since postpartum bodies, exhaustion, and touch tolerance change fast and partners often assume the other feels the same way they do. One partner may be ready for touch sooner or later than the other, and both may be carrying unspoken worry about rejecting or pressuring the other. Name early on that intimacy includes non-sexual touch, and that the goal here is an honest baseline conversation, not a plan to fix anything by next week.', '[{"id": "f0", "type": "textarea", "label": "What kind of touch feels good to you right now, and what feels like too much?"}, {"id": "f1", "type": "textarea", "label": "What has changed in how your body feels since birth that your partner should know?"}, {"id": "f2", "type": "textarea", "label": "What are you afraid your partner is thinking about this part of your relationship?"}, {"id": "f3", "type": "textarea", "label": "What is one small way you''d like more closeness this week, sexual or not?"}, {"id": "f4", "type": "textarea", "label": "What do you want your partner to know you need from them right now?"}]'::jsonb, array['perinatal and postpartum', 'relationship issues', 'communication', 'intimacy']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('becoming-a-big-sibling-craft', 'Becoming a Big Sibling Craft', 'kids'::resource_kind, 'A craft activity where a child decorates a keepsake box for feelings about a new baby in the house.', 'Use it to give an older sibling a hands-on way to name mixed feelings about a new baby.', array['Children']::text[], '30 minutes', 'The child decorates a small box, then the parent helps them add drawings or notes for feelings that come up about the new baby, including ones that feel less allowed, like jealousy or wanting less attention on the baby. Keep supplies open-ended, such as stickers, markers, and stamps, and let the child lead the pace over one or two sittings. Parents often expect only love and excitement here, so coach them beforehand to welcome whatever the child brings, including anger, and to avoid rushing past hard feelings toward reassurance.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one thing you like about having a new baby at home."}, {"id": "f1", "type": "textarea", "label": "Draw or write one thing that feels hard or annoying about it."}, {"id": "f2", "type": "textarea", "label": "Draw a time you felt left out or wanted more attention."}, {"id": "f3", "type": "textarea", "label": "Draw or write one job a big sibling gets to do that a baby can''t."}, {"id": "f4", "type": "textarea", "label": "What is one thing you want your parent to know about how you feel?"}]'::jsonb, array['perinatal and postpartum', 'children', 'family', 'art']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('new-parent-ask-for-help-bingo', 'New Parent Ask-for-Help Bingo', 'game'::resource_kind, 'A bingo game where new parents mark off small tasks they are willing to hand off to their support network.', 'Use it to make delegating help feel playful instead of like admitting failure.', array['Adults', 'Groups']::text[], '20 minutes', 'In a new-parent group, hand out bingo cards filled with squares like a meal drop-off, an hour of baby holding, a load of laundry, or a grocery run, and have each player mark a square once they name a specific person they could ask. Play a round where players share out loud what stopped them from asking before, since guilt, pride, and not wanting to seem like they can''t cope come up often. Debrief by asking each player to pick one square to actually ask for before the group meets again.', '[{"id": "f0", "type": "textarea", "label": "Which square was hardest for you to imagine asking for, and why?"}, {"id": "f1", "type": "textarea", "label": "Who is one person you could realistically ask this week?"}, {"id": "f2", "type": "textarea", "label": "What do you usually tell yourself when you consider asking for help?"}, {"id": "f3", "type": "textarea", "label": "What would you say to a friend who felt guilty asking for the same thing?"}, {"id": "f4", "type": "textarea", "label": "What is the one square you''re committing to ask for before we meet again?"}]'::jsonb, array['perinatal and postpartum', 'support', 'group']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('new-parent-identity-shift-worksheet', 'New Parent Identity Shift Worksheet', 'worksheet'::resource_kind, 'A worksheet that helps a new parent name what has changed and what still feels like them since becoming a parent.', 'Use it to normalize the identity change that often comes with early parenthood.', array['Adults']::text[], '25 minutes', 'New parents often arrive describing a loss of self they can''t quite name, caught between loving the baby and grieving parts of their old life, work identity, or body. Use this worksheet to make that shift explicit rather than something to feel guilty about, and normalize that identity change after birth can take a year or more to settle. Watch for clients who read any grief for their old life as evidence they are bad parents; the goal is naming the shift, not resolving it in one session.', '[{"id": "f0", "type": "textarea", "label": "What is one part of your life before the baby that you miss?"}, {"id": "f1", "type": "textarea", "label": "What is one part of yourself that feels unfamiliar since becoming a parent?"}, {"id": "f2", "type": "textarea", "label": "What is one part of your old self that is still fully there?"}, {"id": "f3", "type": "textarea", "label": "What is something about this new version of you that you''re starting to like?"}, {"id": "f4", "type": "textarea", "label": "What would you want to say to the person you were a year ago?"}]'::jsonb, array['perinatal and postpartum', 'self-compassion', 'life review']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('bases-of-self-worth-pie-chart', 'Bases of Self-Worth Pie Chart', 'cbt'::resource_kind, 'A CBT pie chart exercise mapping how much a client''s sense of worth rests on each part of their life.', 'Use it to show a client how narrowly their self-worth is resting on one or two areas.', array['Adults']::text[], '20 minutes', 'Have the client list every area their self-worth currently rests on, such as work performance, appearance, being liked, or being a good parent, then draw a pie chart sizing each slice by how much weight it actually carries day to day. Most clients discover one or two oversized slices doing all the work, which explains why a single setback in that area can tank their mood. Follow up by sketching a second, more balanced pie together and naming small ways to grow the underused slices over time.', '[{"id": "f0", "type": "textarea", "label": "List every area your sense of worth currently depends on."}, {"id": "f1", "type": "textarea", "label": "Draw a pie chart sizing each area by how much it actually affects your mood."}, {"id": "f2", "type": "textarea", "label": "Which slice is doing the most work, and what happens to you when it wobbles?"}, {"id": "f3", "type": "textarea", "label": "What is one underused area you''d like to grow?"}, {"id": "f4", "type": "textarea", "label": "What would a more balanced pie chart look like for you?"}]'::jsonb, array['self-esteem', 'core beliefs', 'self-monitoring']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('not-good-enough-story-defusion', 'The Not Good Enough Story Defusion', 'act'::resource_kind, 'An ACT defusion exercise that helps a client notice and unhook from a familiar not-good-enough story.', 'Use it to loosen the grip of a chronic self-judgment without arguing it true or false.', array['Adults']::text[], '15 minutes', 'Have the client name their version of the story in a few words, then practice noticing it as a mental habit with a name rather than a fact, saying I''m having the not good enough story again instead of I am not good enough. Repeat it slowly, in a silly voice, or written on a card the client can hold up, so the words lose some of their pull. Some clients resist because the story feels true and dropping it feels like giving up standards; clarify that defusion changes their relationship to the thought, not whether it''s accurate.', '[{"id": "f0", "type": "textarea", "label": "In a few words, what is your version of the not-good-enough story?"}, {"id": "f1", "type": "textarea", "label": "When does this story tend to show up loudest?"}, {"id": "f2", "type": "textarea", "label": "What does the story usually make you do or avoid?"}, {"id": "f3", "type": "textarea", "label": "Say the story out loud starting with I''m having the thought that. How does that feel different?"}, {"id": "f4", "type": "textarea", "label": "If the story showed up but you didn''t have to obey it, what would you do instead?"}]'::jsonb, array['self-esteem', 'defusion', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('non-judgmental-self-talk-practice', 'Non-Judgmental Self-Talk Practice', 'dbt'::resource_kind, 'A DBT mindfulness exercise that trains a client to describe themselves without judgment-laden labels.', 'Use it to build the habit of a non-judgmental stance toward the client''s own behavior and choices.', array['Adults']::text[], '15 minutes', 'Ask the client to describe a recent moment they judged themselves harshly, first in their usual judgmental words, then again using only observable facts, stripping out words like stupid, lazy, or failure. This is harder than it sounds, since judgment often feels like the truth rather than an add-on, so model the rewrite together the first few times. Clients with a loud self-critic may resist, worried that dropping judgment means dropping standards or accountability; clarify that facts can still guide a change in behavior without the insult attached.', '[{"id": "f0", "type": "textarea", "label": "Describe a moment you judged yourself harshly, in your usual words."}, {"id": "f1", "type": "textarea", "label": "Now describe the same moment using only facts, no judgment words."}, {"id": "f2", "type": "textarea", "label": "What judgment word did you catch yourself using most?"}, {"id": "f3", "type": "textarea", "label": "What would you say to a friend who described the same facts about themselves?"}, {"id": "f4", "type": "textarea", "label": "What is one non-judgmental phrase you could use next time this comes up?"}]'::jsonb, array['self-esteem', 'mindfulness', 'self-talk']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('how-my-partner-sees-me-exercise', 'How My Partner Sees Me Exercise', 'couples'::resource_kind, 'A couples exercise where each partner writes down strengths they see in the other to counter one-sided self-criticism.', 'Use it to give a client external evidence against their self-critical view, drawn from someone who knows them well.', array['Couples']::text[], '20 minutes', 'Have each partner privately list strengths and qualities they admire in the other, then read the list aloud while the receiving partner simply listens without deflecting or arguing the points. Clients with low self-esteem often want to correct or minimize what they hear, so coach the receiving partner beforehand to practice just saying thank you. This works best paired with a brief talk about how one partner''s self-esteem can quietly shape the relationship, so the listening partner understands why this exercise matters.', '[{"id": "f0", "type": "textarea", "label": "List three strengths or qualities you admire in your partner."}, {"id": "f1", "type": "textarea", "label": "Describe a specific moment your partner showed one of these strengths."}, {"id": "f2", "type": "textarea", "label": "As the listener, what was hard about hearing this without arguing it?"}, {"id": "f3", "type": "textarea", "label": "What is one thing on this list that surprised you?"}, {"id": "f4", "type": "textarea", "label": "What is one strength you''d like your partner to remind you of on a hard day?"}]'::jsonb, array['self-esteem', 'relationship issues', 'strengths']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('pride-shield-building-craft', 'Pride Shield Building Craft', 'kids'::resource_kind, 'A craft where a child builds and decorates a paper shield with things they''re proud of about themselves.', 'Use it to give a child a concrete, visible reminder of their own strengths.', array['Children']::text[], '30 minutes', 'The child cuts and decorates a shield shape, dividing it into sections for things like something I''m good at, something kind I did, and something I tried even though it was hard. Parents help by adding an observation of their own in one section, since children with low self-esteem often can''t generate examples alone and need a prompt from someone who knows them. Send the shield home to hang somewhere visible, and coach the parent to reference it in passing rather than turning it into a lecture.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one thing you''re good at."}, {"id": "f1", "type": "textarea", "label": "Draw or write one kind thing you did for someone."}, {"id": "f2", "type": "textarea", "label": "Draw or write one hard thing you tried, even if it didn''t go perfectly."}, {"id": "f3", "type": "textarea", "label": "Ask your grown-up to write one thing they''re proud of you for."}, {"id": "f4", "type": "textarea", "label": "Where will you hang your shield so you can see it?"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'art']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('small-talk-roulette', 'Small Talk Roulette', 'game'::resource_kind, 'A group game where players spin for a small-talk prompt and practice starting a brief conversation.', 'Use it to give clients low-stakes reps at initiating conversation before trying it outside session.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Players take turns spinning or drawing a prompt card, like asking about a weekend or commenting on the weather, then practice delivering it to a partner for thirty seconds before switching. Keep the first round low-pressure by letting players pass once, since the fear of freezing up is often the biggest barrier, not the content of what to say. In the debrief, ask what physical sensations came up and how the actual conversation compared to what they predicted beforehand, since predictions in social anxiety usually run far worse than reality.', '[{"id": "f0", "type": "textarea", "label": "Which prompt felt easiest to deliver, and which felt hardest?"}, {"id": "f1", "type": "textarea", "label": "What did you predict would happen before you spoke?"}, {"id": "f2", "type": "textarea", "label": "What actually happened when you spoke?"}, {"id": "f3", "type": "textarea", "label": "What physical sensations came up while you waited your turn?"}, {"id": "f4", "type": "textarea", "label": "What is one small-talk opener you''d be willing to try outside this room?"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-reality-check', 'Spotlight Effect Reality Check', 'worksheet'::resource_kind, 'A worksheet that compares how closely a client thinks others noticed a mistake with how much they likely actually did.', 'Use it to loosen the belief that others are watching and judging as closely as it feels.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk the client through a recent moment they felt embarrassed in public, having them rate how much they believe others noticed and remembered it, then compare that to how much they themselves remember about other people''s small stumbles from the same week. Most clients draw a blank trying to recall others'' minor mishaps, which makes the point better than explaining it would. Some clients argue their situation was different or worse; stay curious rather than debating, and let the exercise do the work over a few repetitions.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent moment you felt embarrassed in front of others."}, {"id": "f1", "type": "textarea", "label": "On a scale of 0 to 100, how much do you think others noticed and remembered it?"}, {"id": "f2", "type": "textarea", "label": "Now think of someone else''s small stumble this week. How much do you remember about it?"}, {"id": "f3", "type": "textarea", "label": "What does that gap suggest about how closely people are actually watching you?"}, {"id": "f4", "type": "textarea", "label": "What would you tell a friend who was sure everyone noticed their mistake?"}]'::jsonb, array['social anxiety', 'thinking traps', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('social-risk-taking-experiment-log', 'Social Risk-Taking Experiment Log', 'cbt'::resource_kind, 'A CBT log for testing a specific social prediction against what actually happens when a client takes the risk.', 'Use it to replace avoidance with small, testable social risks and real feedback.', array['Adults', 'Teens']::text[], 'One week', 'Have the client pick one small social risk to try this week, like asking a question in a meeting or texting a friend first, and write down their prediction before doing it, including how bad they expect it to feel and for how long. After the attempt, they log what actually happened and how long any discomfort lasted, which is usually far shorter than predicted. Review the gap together in session rather than letting the client dismiss a good outcome as luck; the pattern across several logs is what shifts the belief, not any single entry.', '[{"id": "f0", "type": "textarea", "label": "What is the small social risk you''re going to try this week?"}, {"id": "f1", "type": "textarea", "label": "What do you predict will happen, and how bad do you expect it to feel?"}, {"id": "f2", "type": "textarea", "label": "How long do you predict the discomfort will last?"}, {"id": "f3", "type": "textarea", "label": "What actually happened when you tried it?"}, {"id": "f4", "type": "textarea", "label": "How long did the discomfort actually last, compared to your prediction?"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('theyre-all-judging-me-defusion-drill', 'They''re All Judging Me Defusion Drill', 'act'::resource_kind, 'An ACT defusion drill for the automatic thought that everyone in a room is judging the client.', 'Use it to help a client notice the judging thought as a mental habit rather than a fact about the room.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client bring to mind a room where the everyone''s judging me thought shows up loudest, then repeat the thought slowly out loud several times until the words start to lose their usual pull, a classic defusion technique. Follow it by having the client name the thought as a visitor, saying there''s the judging thought again rather than treating it as news about the room. Some clients push back that the thought protects them from getting hurt; validate the function without agreeing the thought is accurate, and steer back toward what they''d do if the thought were just background noise.', '[{"id": "f0", "type": "textarea", "label": "What room or situation does the everyone''s judging me thought hit hardest in?"}, {"id": "f1", "type": "textarea", "label": "Say the thought out loud slowly, several times. What happens to it?"}, {"id": "f2", "type": "textarea", "label": "What does this thought usually get you to do or avoid?"}, {"id": "f3", "type": "textarea", "label": "If this thought showed up but you didn''t have to listen to it, what would you do?"}, {"id": "f4", "type": "textarea", "label": "What is one value you''d be moving toward if you let the thought just pass through?"}]'::jsonb, array['social anxiety', 'defusion', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('participate-skill-for-mingling', 'Participate Skill for Mingling', 'dbt'::resource_kind, 'A DBT mindfulness exercise using the participate skill to help a client engage in a social setting without over-planning.', 'Use it to shift a client out of scripting every word in advance and into the moment instead.', array['Adults', 'Teens']::text[], '15 minutes', 'Before a planned social event, have the client practice the participate skill by picking one low-stakes activity, like a short walk-and-talk with a friend, and entering it without a script, letting themselves act without extensive pre-planning. Debrief afterward on what came up when they weren''t rehearsing lines in their head, since clients with social anxiety often over-plan as a safety behavior that keeps them half out of the conversation. Note where the urge to script returned strongest, since that''s usually the spot worth practicing again.', '[{"id": "f0", "type": "textarea", "label": "What social moment are you going to practice entering without a script?"}, {"id": "f1", "type": "textarea", "label": "What did you notice when you weren''t rehearsing what to say?"}, {"id": "f2", "type": "textarea", "label": "Where did the urge to plan ahead come back strongest?"}, {"id": "f3", "type": "textarea", "label": "What happened in the conversation that you couldn''t have scripted anyway?"}, {"id": "f4", "type": "textarea", "label": "What would it look like to participate this way again next week?"}]'::jsonb, array['social anxiety', 'mindfulness', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('grief-pace-mismatch-map', 'Grief Pace Mismatch Map', 'couples'::resource_kind, 'Compares how each partner grieves and paces so neither reads the other''s quiet as indifference.', 'Turn a mismatch in grieving styles into a shared plan instead of a silent wedge between partners.', array['Couples', 'Adults']::text[], '30 minutes', 'One partner may cry and talk, the other go quiet and stay busy; each can read the other''s style as not caring. Have each partner describe their own pattern first, then guess the other''s before checking it against what their partner actually wrote. Focus on what each one needs from the other during a hard stretch, not on making the styles match.', '[{"id": "f0", "type": "textarea", "label": "How I grieve, in my own words"}, {"id": "f1", "type": "textarea", "label": "How I think my partner grieves"}, {"id": "f2", "type": "textarea", "label": "What I''ve assumed about my partner''s quiet stretches"}, {"id": "f3", "type": "textarea", "label": "What I actually need from my partner when I''m grieving hard"}, {"id": "f4", "type": "textarea", "label": "What my partner actually needs from me when they''re grieving hard"}, {"id": "f5", "type": "textarea", "label": "One thing we''ll do differently around a hard date"}]'::jsonb, array['grief and loss', 'relationships', 'communication']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('memory-quilt-square-craft', 'Memory Quilt Square Craft', 'kids'::resource_kind, 'A child decorates a paper square about the person who died, later joined with squares from the rest of the family.', 'Give a grieving child something to make and a way into the family''s shared mourning, not just their own.', array['Children', 'Teens']::text[], '30 minutes, then ongoing', 'Give the child paper, fabric scraps, markers and glue, and let them choose colors, words or small objects that remind them of the person; there is no wrong square. Coach the parent or caregiver to make their own square alongside the child rather than direct the child''s. Join the finished squares into one quilt or poster the family can see, and bring it out again on birthdays or the anniversary.', '[{"id": "f0", "type": "textarea", "label": "What''s on my square, and why I picked it"}, {"id": "f1", "type": "textarea", "label": "A color I used and what it means to me"}, {"id": "f2", "type": "textarea", "label": "A memory that goes with my square"}, {"id": "f3", "type": "textarea", "label": "What I noticed on someone else''s square"}, {"id": "f4", "type": "textarea", "label": "Where I want our quilt to hang"}]'::jsonb, array['grief and loss', 'children', 'art', 'family']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('guess-who-remembers-game', 'Guess Who Remembers Game', 'game'::resource_kind, 'Family members write memories of the person who died anonymously, then the group guesses who wrote each one.', 'Show a grieving family how differently each person loved and remembers the same person.', array['Children', 'Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player writes two or three short memories on cards without a name, or dictates them to the clinician if too young to write; shuffle the cards and read them aloud one at a time while the group guesses the author. There are no wrong guesses and no scorekeeping. Debrief on which memory surprised the group and what it showed about the person that no single member knew alone.', '[{"id": "f0", "type": "textarea", "label": "The memories I wrote"}, {"id": "f1", "type": "textarea", "label": "A memory I guessed correctly"}, {"id": "f2", "type": "textarea", "label": "A memory that surprised me"}, {"id": "f3", "type": "textarea", "label": "My favorite memory someone else shared"}, {"id": "f4", "type": "textarea", "label": "Something I learned about the person I didn''t know before"}]'::jsonb, array['grief and loss', 'family', 'play', 'group']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('secondary-losses-inventory', 'Secondary Losses Inventory', 'worksheet'::resource_kind, 'Lists the roles, routines and plans that changed under the main loss, which grief work often skips past.', 'Name the layered losses under the death itself so the work doesn''t stall on the obvious loss alone.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients usually name only the death itself; ask directly what else changed under it: a role (spouse, caregiver, only child), a routine, an income, a plan for the future, a sense of identity. Each secondary loss can be grieved on its own terms and often explains a reaction that seems disproportionate to the main loss. Revisit the list as new secondary losses surface over the following months.', '[{"id": "f0", "type": "textarea", "label": "The main loss"}, {"id": "f1", "type": "textarea", "label": "A role of mine that changed because of it"}, {"id": "f2", "type": "textarea", "label": "A routine or plan that no longer applies"}, {"id": "f3", "type": "textarea", "label": "A part of how I see myself that shifted"}, {"id": "f4", "type": "textarea", "label": "Which of these hits hardest right now"}, {"id": "f5", "type": "textarea", "label": "One person who can help with one item on this list"}]'::jsonb, array['grief and loss', 'identity', 'life review']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('if-only-thoughts-log', 'If-Only Thoughts Log', 'cbt'::resource_kind, 'Catches the if-only and should-have thoughts that follow a loss and tests them against what was knowable then.', 'Loosen guilt attached to a choice the client could not have made differently with what they knew then.', array['Adults', 'Teens']::text[], '25 minutes', 'Grief often comes with a running list of things the client believes they should have said, noticed or done differently. For each one, log the thought, then separate what the client actually knew at that moment from what only became clear in hindsight. Rate belief in the thought before and after; expect it to drop slowly rather than all at once, and repeat with new if-only thoughts as they surface.', '[{"id": "f0", "type": "textarea", "label": "The if-only or should-have thought"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now (0-100%)"}, {"id": "f2", "type": "textarea", "label": "What I actually knew at that moment"}, {"id": "f3", "type": "textarea", "label": "What I only learned afterward, with hindsight"}, {"id": "f4", "type": "textarea", "label": "A fairer statement about that moment"}, {"id": "f5", "type": "textarea", "label": "How much I believe the fairer statement now (0-100%)"}]'::jsonb, array['grief and loss', 'guilt', 'thinking traps']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('partner-story-defusion-drill', 'Partner Story Defusion Drill', 'act'::resource_kind, 'Separates what a partner actually did from the story the mind adds about what it means.', 'Help the client respond to a partner''s actual behavior instead of the mind''s interpretation of it.', array['Couples', 'Adults']::text[], '20 minutes', 'Pick a recent moment that stung. Have the client write the bare facts first, only what a camera would have recorded, then write the story the mind built on top: what it means about the partner, the relationship, or them. Say the story aloud with a defusion frame like ''I''m having the thought that'' and notice it loosen. The facts rarely need as strong a reaction as the story does.', '[{"id": "f0", "type": "textarea", "label": "The moment (bare facts only, like a camera would see it)"}, {"id": "f1", "type": "textarea", "label": "The story my mind added about what it means"}, {"id": "f2", "type": "textarea", "label": "Saying it as ''I''m having the thought that...'' plus the story"}, {"id": "f3", "type": "textarea", "label": "What changes about the moment once I say it that way"}, {"id": "f4", "type": "textarea", "label": "How I want to respond to the facts alone"}]'::jsonb, array['relationship issues', 'defusion', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('ask-priorities-check-for-partners', 'Ask Priorities Check for Partners', 'dbt'::resource_kind, 'Weighs getting the outcome, keeping the relationship and keeping self-respect before a hard ask of a partner.', 'Help the client choose how hard to push a request based on what matters most to them this time.', array['Couples', 'Adults']::text[], '15 minutes', 'Before scripting the ask itself, have the client rank three priorities for this particular request: getting the outcome, protecting the relationship, and keeping their own self-respect. A request about splitting chores might weigh differently than one about a boundary that was crossed. The ranking changes how firm, how soft, and how much the client is willing to give up to get it, and prevents an ask that wins the point but costs the relationship.', '[{"id": "f0", "type": "textarea", "label": "What I want to ask my partner for"}, {"id": "f1", "type": "textarea", "label": "How much getting this outcome matters (1-10)"}, {"id": "f2", "type": "textarea", "label": "How much protecting the relationship matters here (1-10)"}, {"id": "f3", "type": "textarea", "label": "How much my own self-respect matters here (1-10)"}, {"id": "f4", "type": "textarea", "label": "Which priority wins if I have to choose"}, {"id": "f5", "type": "textarea", "label": "How that changes what I''ll say"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'decisions']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('negative-sentiment-check-for-partners', 'Negative Sentiment Check for Partners', 'couples'::resource_kind, 'Tests whether a partner is reading neutral or kind moves as negative because goodwill has worn thin.', 'Catch a flipped lens before it colors every interaction, so repair can start there and not just on the fights.', array['Couples', 'Adults']::text[], '25 minutes', 'List several genuinely neutral or mildly positive things the partner did this week: texted a reminder, loaded the dishwasher a certain way, came home a few minutes late. Have each partner rate how they read it in the moment: neutral, kind, or as a dig. A pattern of reading neutral acts as hostile signals negative sentiment override, and the couple needs to rebuild goodwill before content-level fixes like scripts or chore charts will hold.', '[{"id": "f0", "type": "textarea", "label": "Something neutral or kind my partner did this week"}, {"id": "f1", "type": "textarea", "label": "How I read it in the moment"}, {"id": "f2", "type": "textarea", "label": "How I''d read the same thing on a good week"}, {"id": "f3", "type": "textarea", "label": "What tells me goodwill is running low right now"}, {"id": "f4", "type": "textarea", "label": "One thing we''ll do this week to rebuild it"}]'::jsonb, array['relationship issues', 'Gottman', 'pattern']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('friendship-repair-recipe-card', 'Friendship Repair Recipe Card', 'kids'::resource_kind, 'A child builds a step-by-step recipe card for repairing a fight with a friend.', 'Give a child a concrete order of steps to follow after a friendship fight instead of freezing or avoiding.', array['Children', 'Teens']::text[], '20 minutes', 'Have the child decorate an index card with numbered steps in their own words and pictures, such as calm down first, say what happened, say sorry for their part, ask what the friend needs, and plan something fun together. Keep the parent''s role to rehearsing the card with the child at home before it''s needed and prompting ''what''s step one?'' in the moment rather than solving the fight for them.', '[{"id": "f0", "type": "textarea", "label": "Step 1 on my card"}, {"id": "f1", "type": "textarea", "label": "Step 2 on my card"}, {"id": "f2", "type": "textarea", "label": "Step 3 on my card"}, {"id": "f3", "type": "textarea", "label": "A fight I could use my card for"}, {"id": "f4", "type": "textarea", "label": "Who can practice this with me at home"}]'::jsonb, array['relationship issues', 'children', 'repair']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('repair-attempt-roleplay-round', 'Repair Attempt Roleplay Round', 'game'::resource_kind, 'Partners rehearse mid-argument repair phrases on low-stakes scripted scenarios before they need them live.', 'Make repair attempts automatic under mild stress instead of something a partner has to invent mid-fight.', array['Couples', 'Adults']::text[], '30 minutes', 'Write several mild, scripted disagreement scenarios on cards beforehand. One partner draws a card and plays a lightly escalating role while the other practices deploying a repair attempt from an agreed list: a raised hand, a code word, a moment of humor. Swap roles each round. Keep the scenarios genuinely low-stakes; the goal is rehearsal, not reopening a real fight. Debrief on which repair attempts felt natural and which felt forced.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "The repair attempt I tried"}, {"id": "f2", "type": "textarea", "label": "How my partner responded to it"}, {"id": "f3", "type": "textarea", "label": "A repair attempt that felt natural to me"}, {"id": "f4", "type": "textarea", "label": "A repair attempt that felt forced"}, {"id": "f5", "type": "textarea", "label": "The one I want to use for real this week"}]'::jsonb, array['relationship issues', 'repair', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('session-pacing-agreement', 'Session Pacing Agreement', 'worksheet'::resource_kind, 'Agreed signals a client can use in session to slow down, pause or stop without having to explain why.', 'Give a survivor real control over pace before deeper work begins, not just control in principle.', array['Adults', 'Teens']::text[], '20 minutes', 'Complete this together in session, not as homework. Agree on a pause word or hand signal, what the clinician will do when it''s used, and how often to check in during harder stretches of work. Ask what it looks like when the client freezes or goes quiet rather than using the signal, since that is common, and agree on what the clinician should do then. This sheet does not ask for any detail about what happened.', '[{"id": "f0", "type": "textarea", "label": "My pause word or signal"}, {"id": "f1", "type": "textarea", "label": "What I want you to do when I use it"}, {"id": "f2", "type": "textarea", "label": "What it looks like when I freeze instead of signaling"}, {"id": "f3", "type": "textarea", "label": "What I want you to do if that happens"}, {"id": "f4", "type": "textarea", "label": "How often I want you to check in during harder work"}, {"id": "f5", "type": "textarea", "label": "What I want to decide is always my choice"}]'::jsonb, array['sexual abuse', 'PTSD and trauma', 'grounding']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('safety-judgment-continuum', 'Safety Judgment Continuum', 'cbt'::resource_kind, 'Rates how safe specific present-day people and situations actually are against a blanket no-one-is-safe alarm.', 'Loosen an all-or-nothing danger belief without asking the client to revisit what happened.', array['Adults', 'Teens']::text[], '20 minutes', 'Stay entirely in the present for this one. List specific people or situations from the client''s current life and have them rate each one''s danger from 0 to 100, then note what evidence supports and challenges that rating. Survivors often carry an all-or-nothing alarm that reads everyone as equally unsafe; the continuum makes the real differences visible. Do not ask for any account of the past event itself.', '[{"id": "f0", "type": "textarea", "label": "A person or situation from my life right now"}, {"id": "f1", "type": "textarea", "label": "My danger rating for it (0-100)"}, {"id": "f2", "type": "textarea", "label": "Evidence that supports this rating"}, {"id": "f3", "type": "textarea", "label": "Evidence that challenges this rating"}, {"id": "f4", "type": "textarea", "label": "A more accurate rating"}, {"id": "f5", "type": "textarea", "label": "What''s actually different about the people I rate as safer"}]'::jsonb, array['sexual abuse', 'PTSD and trauma', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('then-versus-now-anchoring-practice', 'Then Versus Now Anchoring Practice', 'act'::resource_kind, 'Uses present-moment senses to mark the difference between the danger that happened then and the safety here now.', 'Build a fast, rehearsed way back to the present when a reminder pulls the client into the past.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice this while calm, well before it''s needed live, and never as a way to draw out the narrative; the point is contrast, not content. Have the client name, in general terms only, one thing true of ''then'' and pair it with something only true of ''now'': this room, this year, this choice, this body at an age it wasn''t then. Anchor the ''now'' side to a physical action like planting both feet, and rehearse the pairing until it''s quick.', '[{"id": "f0", "type": "textarea", "label": "One thing true of ''then,'' in general terms only"}, {"id": "f1", "type": "textarea", "label": "One thing only true of ''now''"}, {"id": "f2", "type": "textarea", "label": "My physical anchor for ''now'' (feet, hands, breath)"}, {"id": "f3", "type": "textarea", "label": "A word or phrase that means ''now'' to me"}, {"id": "f4", "type": "textarea", "label": "When I''ll practice this on purpose this week"}]'::jsonb, array['sexual abuse', 'PTSD and trauma', 'grounding']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('body-alarm-radical-acceptance-practice', 'Body Alarm Radical Acceptance Practice', 'dbt'::resource_kind, 'Applies radical acceptance to the body''s leftover alarm reactions so the client stops fighting a response it can''t outthink.', 'Reduce the added suffering of judging a startle or freeze reaction as wrong or broken.', array['Adults', 'Teens']::text[], '20 minutes', 'A startle, a freeze, a flinch at an ordinary touch: these are the body''s alarm system doing its job late, not a sign anything is currently wrong with the client. Log the reaction, then the judgment the mind adds about it, then a radical acceptance statement that names the reaction as understandable given the body''s history without agreeing it means danger now. Pair with one self-soothe step. Fighting the reaction tends to prolong it; naming it tends to let it pass.', '[{"id": "f0", "type": "textarea", "label": "The reaction (startle, freeze, flinch...)"}, {"id": "f1", "type": "textarea", "label": "What my mind says about having this reaction"}, {"id": "f2", "type": "textarea", "label": "A radical acceptance statement about it"}, {"id": "f3", "type": "textarea", "label": "One self-soothe step I used afterward"}, {"id": "f4", "type": "textarea", "label": "How long the reaction lasted this time"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'PTSD and trauma']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('partner-support-and-pace-agreement', 'Partner Support and Pace Agreement', 'couples'::resource_kind, 'Agreed roles for a partner supporting a survivor: what helps, what to avoid, and who sets the pace for touch.', 'Turn a partner''s wish to help into welcomed, concrete actions instead of guesses that can retraumatize.', array['Couples', 'Adults']::text[], '30 minutes', 'Complete this together in session, and keep it about present-day needs, not the history of what happened. Cover touch and how the survivor wants to signal not now, how the partner should check in without hovering, what to do if the survivor freezes or goes somewhere else in their mind, and how the partner manages their own hurt or frustration without asking the survivor to reassure them. Review it again after it''s been tried.', '[{"id": "f0", "type": "textarea", "label": "Touch or closeness that feels okay right now"}, {"id": "f1", "type": "textarea", "label": "How I''ll signal ''not now'' to my partner"}, {"id": "f2", "type": "textarea", "label": "How I want my partner to check in without hovering"}, {"id": "f3", "type": "textarea", "label": "What my partner should do if I freeze or go quiet"}, {"id": "f4", "type": "textarea", "label": "Where I''ll take my own hard feelings instead of to you"}, {"id": "f5", "type": "textarea", "label": "When we''ll revisit this agreement"}]'::jsonb, array['sexual abuse', 'support', 'PTSD and trauma']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-craft', 'Coping Toolbox Craft', 'kids'::resource_kind, 'A shoebox a child paints and fills with drawn or written reminders of their go-to coping skills.', 'Give a child a hands-on reminder of the coping skills they can reach for when big feelings hit.', array['Children']::text[], '30 minutes', 'Bring a small box, paper, markers, and glue to session. The child decorates the outside as their own toolbox, then fills it with slips naming or drawing skills that help them calm down, like squeezing a stress ball or taking slow breaths. Some children want to fill it with small toys instead of paper; let them, and write the skill on a tag tied to each item. Send the box home and ask the parent to keep it somewhere the child can reach it alone.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one thing that helps you calm your body."}, {"id": "f1", "type": "textarea", "label": "Draw or write one thing that helps you calm your mind."}, {"id": "f2", "type": "textarea", "label": "Who is someone you can go to when you need help calming down?"}, {"id": "f3", "type": "textarea", "label": "Where will you keep your toolbox so you can find it fast?"}]'::jsonb, array['coping skills', 'children', 'play', 'self-soothing']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('coping-skill-swap', 'Coping Skill Swap', 'game'::resource_kind, 'A trading-card game where players swap coping skills that fit different feelings and situations.', 'Build a wider coping repertoire by having players teach each other what actually works for them.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player writes three coping skills they already use on index cards, one per card, then the group mixes all the cards into a shared deck. Players take turns drawing a card and describing a moment when that skill would help, then decide whether to keep it or trade it back in. Round out the game with a debrief on which traded skills people plan to actually try, and which ones only sound good on paper. Works well in a group session or with a family stuck using the same one or two skills.', '[{"id": "f0", "type": "textarea", "label": "Which three coping skills did you bring to the deck?"}, {"id": "f1", "type": "textarea", "label": "Which skill did you trade for, and why did it catch your attention?"}, {"id": "f2", "type": "textarea", "label": "What situation would you try a new skill in this week?"}, {"id": "f3", "type": "textarea", "label": "Which skill sounds good but you''re not sure you''d actually use?"}]'::jsonb, array['coping skills', 'group', 'play', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('coping-skill-effectiveness-tracker', 'Coping Skill Effectiveness Tracker', 'worksheet'::resource_kind, 'A log where a client rates how well each coping skill actually worked in the moment.', 'Help a client tell which coping skills earn a place in their routine and which ones fall flat.', array['Adults', 'Teens']::text[], 'One week', 'After each stressful moment this week, the client jots the situation, the skill they tried, and a quick rating of how much it helped. Bring the sheet back to session and sort the skills into a short list worth repeating and a longer list to retire or adapt. Watch for clients who rate everything as unhelpful because they tried the skill mid-crisis instead of practicing it beforehand; that pattern is worth naming out loud rather than written off as a failed skill.', '[{"id": "f0", "type": "textarea", "label": "What was the situation?"}, {"id": "f1", "type": "textarea", "label": "Which coping skill did you try?"}, {"id": "f2", "type": "textarea", "label": "How much did it help, from not at all to a lot?"}, {"id": "f3", "type": "textarea", "label": "What would you do differently next time?"}]'::jsonb, array['coping skills', 'monitoring', 'self-monitoring', 'skills']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('problem-vs-emotion-focused-coping-sort', 'Problem vs Emotion-Focused Coping Sort', 'cbt'::resource_kind, 'A sorting exercise that separates a client''s coping list into problem-focused and emotion-focused strategies.', 'Show a client when to fix the situation directly and when to focus on managing the feeling instead.', array['Adults', 'Teens']::text[], '25 minutes', 'The client lists recent stressors, then sorts their usual responses into two columns: strategies that change the situation and strategies that change how they feel about it. Many clients lean heavily on one column, using problem-solving on things they cannot control or trying to feel calmer about something they could actually change. Use the sheet to match the strategy to what the stressor allows, and to notice stressors that call for both columns at once.', '[{"id": "f0", "type": "textarea", "label": "List a stressor from the past week."}, {"id": "f1", "type": "textarea", "label": "What could you do to change or fix this situation directly?"}, {"id": "f2", "type": "textarea", "label": "What could help you feel calmer about it, even if it can''t be fixed?"}, {"id": "f3", "type": "textarea", "label": "Which column does this stressor mostly call for?"}]'::jsonb, array['coping skills', 'problem solving', 'core CBT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('coping-strategy-workability-check', 'Coping Strategy Workability Check', 'act'::resource_kind, 'A check-in that asks whether a coping strategy moves a client toward their values or just away from pain.', 'Help a client judge coping strategies by workability instead of by whether they simply feel better.', array['Adults', 'Teens']::text[], '20 minutes', 'For each coping strategy the client names, walk through three questions: does it help in the moment, does it still help the next day, and does it move them toward the life they want or away from it. A strategy can pass the first question and fail the other two, and that gap is the useful part of the conversation. Use it with clients who already have a long coping list but keep reaching for the same short-term fix under pressure.', '[{"id": "f0", "type": "textarea", "label": "Name a coping strategy you use often."}, {"id": "f1", "type": "textarea", "label": "Does it help in the moment? How?"}, {"id": "f2", "type": "textarea", "label": "How does it feel the next day, or a week later?"}, {"id": "f3", "type": "textarea", "label": "Does it move you toward or away from what matters to you?"}]'::jsonb, array['coping skills', 'values', 'willingness', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-phobias-card', 'Opposite Action for Phobias Card', 'dbt'::resource_kind, 'A pocket card that walks a client through opposite action when fear urges them to avoid a specific trigger.', 'Give a client a quick script for approaching a feared object or situation instead of automatically avoiding it.', array['Adults', 'Teens']::text[], '10 minutes', 'Fill the card out together for one specific feared trigger, naming the avoidance urge and a small, all-the-way opposite action the client can actually do. The client carries the card and reads it before or during a planned approach, checking that the action is done fully rather than half-heartedly, since a hesitant approach tends to reinforce the fear instead of easing it. This pairs well with a graded plan rather than the client''s single scariest step first.', '[{"id": "f0", "type": "textarea", "label": "What is the specific thing you''re afraid of?"}, {"id": "f1", "type": "textarea", "label": "What does the fear urge you to do (avoid, leave, check)?"}, {"id": "f2", "type": "textarea", "label": "What is the all-the-way opposite action you''ll practice?"}, {"id": "f3", "type": "textarea", "label": "How will you know you did the full action, not a partial one?"}]'::jsonb, array['phobias', 'distress tolerance', 'avoidance', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('fear-support-script-for-partners', 'Fear Support Script for Partners', 'couples'::resource_kind, 'A worksheet where each partner writes what actually helps and what backfires when fear takes over.', 'Turn a well-meaning partner''s guesswork into a script both people agree on before the next scared moment.', array['Couples']::text[], '30 minutes', 'Partner A describes their fear trigger and what support looks like when it hits, from words to say to whether they want to be touched or given space. Partner B writes what they currently do, and the two compare notes, since partners often default to reassurance, distraction, or pushing to approach faster, and any of those can help one person and frustrate another. Agree on a short script for Partner B to use next time and a signal Partner A can give for what they need in that moment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what does your fear look like from the outside?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps you most in that moment?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what do you usually do when this happens?"}, {"id": "f3", "type": "textarea", "label": "Together: write the script Partner B will try next time."}]'::jsonb, array['phobias', 'support', 'communication', 'relationship issues']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('fear-monster-shrinking-craft', 'Fear Monster Shrinking Craft', 'kids'::resource_kind, 'A child draws their fear as a monster, then shrinks a new version of it after each brave step.', 'Give a child a visual way to see a specific fear get smaller as they practice approaching it.', array['Children']::text[], '20 minutes', 'The child draws their feared thing as a big, detailed monster on a large sheet, naming what makes it scary. After each practiced brave step toward the real trigger, the child draws a smaller version of the monster on a fresh sheet, and the set is taped up in size order. Some children want to give the monster a silly name or voice, which is fine and often loosens the fear''s grip. Ask the parent to keep the drawings visible at home and to point to the row whenever the child manages a new step.', '[{"id": "f0", "type": "textarea", "label": "Draw your scary thing as a monster. What makes it feel big?"}, {"id": "f1", "type": "textarea", "label": "What is one small step you could try toward it?"}, {"id": "f2", "type": "textarea", "label": "Draw the monster again after your step. Is it smaller?"}, {"id": "f3", "type": "textarea", "label": "What would help the monster get even smaller next time?"}]'::jsonb, array['phobias', 'children', 'art', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('courage-ladder-dice-game', 'Courage Ladder Dice Game', 'game'::resource_kind, 'A dice game where each roll sends a player up or down a printed ladder of approach steps toward a feared trigger.', 'Turn a graded approach plan into a low-pressure game that keeps a client moving toward their trigger.', array['Teens', 'Adults', 'Children']::text[], '25 minutes', 'Before play, the client and clinician list five to eight approach steps toward one feared trigger, from easiest to hardest, and number them as rungs on a paper ladder. On their turn, a player rolls a die and moves that many rungs up, describing out loud how it would feel to do that step, and an optional rule sends a nervous player back one rung to retry an easier description. End with a debrief on which rungs felt easiest to talk through and which ones need more practice before they''re attempted for real.', '[{"id": "f0", "type": "textarea", "label": "List your steps from easiest to hardest, one per rung."}, {"id": "f1", "type": "textarea", "label": "Which rung was easiest to talk through today?"}, {"id": "f2", "type": "textarea", "label": "Which rung made your body react the most?"}, {"id": "f3", "type": "textarea", "label": "What would help you feel ready to try that rung for real?"}]'::jsonb, array['phobias', 'exposure', 'hierarchy', 'play']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('phobia-trigger-and-avoidance-map', 'Phobia Trigger and Avoidance Map', 'worksheet'::resource_kind, 'A map of one specific fear, the situations it touches, and every workaround a client uses to dodge it.', 'Show a client how far a single fear has spread into their routines through avoidance and workarounds.', array['Adults', 'Teens']::text[], '20 minutes', 'In the center, the client names the specific feared thing, then draws spokes out to every situation it touches, from the obvious to the roundabout, like driving an extra ten minutes to skip a bridge. Next to each spoke, they note the workaround they use to avoid it. The map usually turns out bigger than clients expect, and that surprise is useful groundwork for building an approach plan, since it shows how much room avoidance has been given rather than kept small.', '[{"id": "f0", "type": "textarea", "label": "Name the specific thing you''re afraid of."}, {"id": "f1", "type": "textarea", "label": "List a situation this fear touches."}, {"id": "f2", "type": "textarea", "label": "What do you do to avoid or work around it?"}, {"id": "f3", "type": "textarea", "label": "How much extra time or effort does that workaround cost you?"}]'::jsonb, array['phobias', 'avoidance', 'triggers', 'exposure']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('appearance-thought-record', 'Appearance Thought Record', 'cbt'::resource_kind, 'A thought record that captures the automatic thought, feeling, and behavior right after a hard appearance moment.', 'Help a client catch and question the automatic thoughts that fire in a hard appearance moment.', array['Adults', 'Teens']::text[], '15 minutes', 'Right after a moment the client notices judging their appearance, they log the situation, the automatic thought, the feeling it brought, and what they did next, like changing clothes again or canceling plans. In session, work through the thought the way any automatic thought gets questioned: what''s the evidence, what would they tell a friend thinking this, and what''s a more balanced version. Watch for clients who use the record to keep dwelling on their appearance; the point is to catch the thought, not to keep looking.', '[{"id": "f0", "type": "textarea", "label": "What was the situation?"}, {"id": "f1", "type": "textarea", "label": "What thought went through your mind about your appearance?"}, {"id": "f2", "type": "textarea", "label": "What did you feel, and how strong was it?"}, {"id": "f3", "type": "textarea", "label": "What did you do next?"}, {"id": "f4", "type": "textarea", "label": "What''s a more balanced way to think about that moment?"}]'::jsonb, array['body image', 'self-esteem', 'core CBT', 'automatic thoughts']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('values-beyond-appearance-sort', 'Values Beyond Appearance Sort', 'act'::resource_kind, 'A card sort that separates a client''s real values from the appearance rules they''ve mistaken for values.', 'Help a client notice how much of their day serves appearance rules rather than what actually matters to them.', array['Adults', 'Teens']::text[], '20 minutes', 'The client sorts a mixed set of value cards and appearance-rule cards, like looking a certain way or collecting compliments, into what genuinely matters to them versus what they''ve absorbed as a rule to follow. Many clients place appearance rules in the values pile at first, and that mix-up is the useful part of the conversation. Move into a short discussion of what time and energy would look like if the appearance rules loosened their grip and the sorted values led instead.', '[{"id": "f0", "type": "textarea", "label": "Sort each card: is this a value or a rule you''ve picked up?"}, {"id": "f1", "type": "textarea", "label": "Which appearance rule takes up the most of your time or energy?"}, {"id": "f2", "type": "textarea", "label": "Which value would you like to give more room to?"}, {"id": "f3", "type": "textarea", "label": "What''s one small action this week that serves that value?"}]'::jsonb, array['body image', 'values', 'defusion', 'core ACT']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-body-practice', 'Radical Acceptance Body Practice', 'dbt'::resource_kind, 'A guided practice that walks a client through radically accepting their body as it is right now.', 'Help a client stop the exhausting fight against how their body looks and move toward acceptance instead.', array['Adults', 'Teens']::text[], '15 minutes', 'Lead the client through the usual radical acceptance steps, but anchored to a specific appearance thought they keep fighting, noticing where the fight shows up in their body and breath. Acceptance here means dropping the internal argument, not approval or giving up on caring for themselves, and that distinction is worth naming clearly since clients often hear acceptance as surrender. Some clients need to practice this daily for weeks before the fight quiets even briefly, so frame one session as a start, not a finish.', '[{"id": "f0", "type": "textarea", "label": "What appearance thought do you keep fighting?"}, {"id": "f1", "type": "textarea", "label": "Where do you feel that fight in your body?"}, {"id": "f2", "type": "textarea", "label": "What would it mean to stop fighting it, just for now?"}, {"id": "f3", "type": "textarea", "label": "What''s one thing acceptance does NOT mean for you here?"}]'::jsonb, array['body image', 'acceptance', 'distress tolerance', 'self-compassion']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('body-image-support-script-for-partners', 'Body Image Support Script for Partners', 'couples'::resource_kind, 'A worksheet where partners agree on what to say, and what to avoid saying, about appearance.', 'Replace guesswork with an agreed script so a partner''s comments help instead of landing wrong.', array['Couples']::text[], '25 minutes', 'Partner A names the comments about appearance that help, from a simple compliment to no comment at all, and the ones that sting even when well-intended, like reassurance that turns into a comparison. Partner B shares comments they''ve been unsure about offering and why. Together, the couple writes a short list of go-to phrases Partner B can use and a signal Partner A can give when a conversation about appearance needs to stop. Revisit the list after a few weeks, since what helps often shifts.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what comments about your appearance actually help?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what comments land wrong, even when well-meant?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what have you been unsure about saying?"}, {"id": "f3", "type": "textarea", "label": "Together: write two phrases Partner B can use going forward."}]'::jsonb, array['body image', 'communication', 'support', 'relationship issues']::text[], '2026-09-21T15:00:00+00:00'::timestamptz),
  ('my-body-can-do-poster', 'My Body Can Do Poster', 'kids'::resource_kind, 'A poster where a child draws all the things their body lets them do, not how it looks.', 'Help a child build a sense of their body as something that does things for them, not something to judge.', array['Children']::text[], '25 minutes', 'Give the child a large sheet and markers, and ask them to draw themselves doing things their body lets them do, like climbing, hugging, dancing, or running fast, one picture per section of the poster. Steer away from any drawing about how the body looks and toward what it does; if a child brings up comments they''ve heard about their appearance, gently note it and keep the poster focused on ability and action. Send the poster home and ask the parent to add a new drawing together each week.', '[{"id": "f0", "type": "textarea", "label": "Draw something fun your body lets you do."}, {"id": "f1", "type": "textarea", "label": "Draw something your body helped you do for someone else."}, {"id": "f2", "type": "textarea", "label": "What is something new you''d like your body to help you try?"}, {"id": "f3", "type": "textarea", "label": "Who could you ask to try it with you?"}]'::jsonb, array['body image', 'children', 'art', 'self-esteem']::text[], '2026-09-21T15:00:00+00:00'::timestamptz)
